/* --- HMAC-BLAKE2S: standard HMAC construction, key=pass, msg=salt (matches mdxfind) --- */
static void compute_hmac_blake2s(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *kpad = (unsigned char *)WS->ctx1;
    unsigned char *inner = (unsigned char *)WS->ctx2;
    int ki, klen = passlen;
    if (klen > 64) {
        blake2s(kpad, 32, pass, klen, NULL, 0);
        klen = 32;
        memset(kpad + 32, 0, 32);
    } else {
        memcpy(kpad, pass, klen);
        memset(kpad + klen, 0, 64 - klen);
    }
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36;
    { unsigned char *ibuf = WS->gp1; /* 64 + saltlen fits in MAXLINE */
      memcpy(ibuf, kpad, 64); memcpy(ibuf + 64, salt, saltlen);
      blake2s(inner, 32, ibuf, 64 + saltlen, NULL, 0);
    }
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36 ^ 0x5c;
    { unsigned char obuf[96];
      memcpy(obuf, kpad, 64); memcpy(obuf + 64, inner, 32);
      blake2s(dest, 32, obuf, 96, NULL, 0);
    }
}

/* --- HMAC-STREEBOG (GOST2012) --- */
/* streebog_final returns bytes in reversed order; mdxfind reverses inner hash
   and key hash before re-feeding. We do the same here. */
static inline void reverse_bytes(unsigned char *buf, int len) {
    int i; unsigned char tmp;
    for (i = 0; i < len / 2; i++) { tmp = buf[i]; buf[i] = buf[len-1-i]; buf[len-1-i] = tmp; }
}

static void compute_hmac_streebog256(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *kpad = (unsigned char *)WS->ctx1;
    unsigned char *inner = (unsigned char *)WS->ctx2;
    streebog_t stx;
    int ki, klen = saltlen;
    if (klen > 64) {
        streebog(kpad, 32, salt, klen);
        reverse_bytes(kpad, 32);
        klen = 32;
        memset(kpad + 32, 0, 32);
    } else {
        memcpy(kpad, salt, klen);
        memset(kpad + klen, 0, 64 - klen);
    }
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36;
    streebog_init(&stx, 32); streebog_update(&stx, kpad, 64); streebog_update(&stx, pass, passlen); streebog_final(inner, &stx);
    reverse_bytes(inner, 32);
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36 ^ 0x5c;
    streebog_init(&stx, 32); streebog_update(&stx, kpad, 64); streebog_update(&stx, inner, 32); streebog_final(dest, &stx);
}

static void compute_hmac_streebog512(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *kpad = (unsigned char *)WS->ctx1;
    unsigned char *inner = (unsigned char *)WS->ctx2;
    streebog_t stx;
    int ki, klen = saltlen;
    if (klen > 64) {
        streebog(kpad, 64, salt, klen);
        reverse_bytes(kpad, 64);
    } else {
        memcpy(kpad, salt, klen);
        memset(kpad + klen, 0, 64 - klen);
    }
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36;
    streebog_init(&stx, 64); streebog_update(&stx, kpad, 64); streebog_update(&stx, pass, passlen); streebog_final(inner, &stx);
    reverse_bytes(inner, 64);
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36 ^ 0x5c;
    streebog_init(&stx, 64); streebog_update(&stx, kpad, 64); streebog_update(&stx, inner, 64); streebog_final(dest, &stx);
}

static void compute_hmac_streebog256_kpass(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *kpad = (unsigned char *)WS->ctx1;
    unsigned char *inner = (unsigned char *)WS->ctx2;
    streebog_t stx;
    int ki, klen = passlen;
    if (klen > 64) {
        streebog(kpad, 32, pass, klen);
        reverse_bytes(kpad, 32);
        klen = 32;
        memset(kpad + 32, 0, 32);
    } else {
        memcpy(kpad, pass, klen);
        memset(kpad + klen, 0, 64 - klen);
    }
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36;
    streebog_init(&stx, 32); streebog_update(&stx, kpad, 64); streebog_update(&stx, salt, saltlen); streebog_final(inner, &stx);
    reverse_bytes(inner, 32);
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36 ^ 0x5c;
    streebog_init(&stx, 32); streebog_update(&stx, kpad, 64); streebog_update(&stx, inner, 32); streebog_final(dest, &stx);
}

static void compute_hmac_streebog512_kpass(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *kpad = (unsigned char *)WS->ctx1;
    unsigned char *inner = (unsigned char *)WS->ctx2;
    streebog_t stx;
    int ki, klen = passlen;
    if (klen > 64) {
        streebog(kpad, 64, pass, klen);
        reverse_bytes(kpad, 64);
    } else {
        memcpy(kpad, pass, klen);
        memset(kpad + klen, 0, 64 - klen);
    }
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36;
    streebog_init(&stx, 64); streebog_update(&stx, kpad, 64); streebog_update(&stx, salt, saltlen); streebog_final(inner, &stx);
    reverse_bytes(inner, 64);
    for (ki = 0; ki < 64; ki++) kpad[ki] ^= 0x36 ^ 0x5c;
    streebog_init(&stx, 64); streebog_update(&stx, kpad, 64); streebog_update(&stx, inner, 64); streebog_final(dest, &stx);
}

/* ================================================================
 * POMELO v2 (PHC submission by Hongjun Wu)
 * Portable implementation: SSE2, NEON, Altivec/VSX, scalar fallback.
 * Extracted from pom.c (Waffle, 2026).
 * ================================================================ */

#if defined(__SSE2__) || (defined(_MSC_VER) && (defined(_M_X64) || defined(_M_AMD64)))
  #define POM_SSE2 1
  #include <emmintrin.h>
  typedef __m128i pom128_t;
  #define POM_ADD(x, y)       _mm_add_epi64((x), (y))
  #define POM_XOR(x, y)       _mm_xor_si128((x), (y))
  #define POM_OR(x, y)        _mm_or_si128((x), (y))
  #define POM_SHL64(x, n)     _mm_slli_epi64((x), (n))
  #define POM_SHR64(x, n)     _mm_srli_epi64((x), (n))
  #define POM_BYTEL8(x)       _mm_slli_si128((x), 8)
  #define POM_BYTER8(x)       _mm_srli_si128((x), 8)
  #define POM_ZERO()          _mm_setzero_si128()
  static inline unsigned long long pom_getlo64(__m128i x) {
    return (unsigned long long)_mm_cvtsi128_si64(x);
  }
  #define POM_GETLO64(x)      pom_getlo64(x)
#elif defined(__ARM_NEON) || defined(__ARM_NEON__)
  #define POM_NEON 1
  #include <arm_neon.h>
  typedef uint64x2_t pom128_t;
  #define POM_ADD(x, y)       vaddq_u64((x), (y))
  #define POM_XOR(x, y)       veorq_u64((x), (y))
  #define POM_OR(x, y)        vorrq_u64((x), (y))
  #define POM_SHL64(x, n)     vshlq_n_u64((x), (n))
  #define POM_SHR64(x, n)     vshrq_n_u64((x), (n))
  static inline pom128_t pom_bytel8(pom128_t x) {
    return vextq_u64(vdupq_n_u64(0), x, 1);
  }
  static inline pom128_t pom_byter8(pom128_t x) {
    return vextq_u64(x, vdupq_n_u64(0), 1);
  }
  #define POM_BYTEL8(x)       pom_bytel8(x)
  #define POM_BYTER8(x)       pom_byter8(x)
  #define POM_ZERO()          vdupq_n_u64(0)
  static inline unsigned long long pom_getlo64(pom128_t x) {
    return vgetq_lane_u64(x, 0);
  }
  #define POM_GETLO64(x)      pom_getlo64(x)
#elif defined(__ALTIVEC__) || defined(__VSX__)
  #define POM_ALTIVEC 1
  #include <altivec.h>
  typedef __vector unsigned long long pom128_t;
  #define POM_ADD(x, y)       vec_add((x), (y))
  #define POM_XOR(x, y)       vec_xor((x), (y))
  #define POM_OR(x, y)        vec_or((x), (y))
  static inline pom128_t pom_shl64(pom128_t x, unsigned int n) {
    pom128_t sv = {n, n}; return vec_sl(x, sv);
  }
  static inline pom128_t pom_shr64(pom128_t x, unsigned int n) {
    pom128_t sv = {n, n}; return vec_sr(x, sv);
  }
  #define POM_SHL64(x, n)     pom_shl64((x), (n))
  #define POM_SHR64(x, n)     pom_shr64((x), (n))
  static inline pom128_t pom_bytel8(pom128_t x) {
    pom128_t zero = {0, 0};
  #ifdef __LITTLE_ENDIAN__
    return vec_sld(x, zero, 8);
  #else
    return vec_sld(zero, x, 8);
  #endif
  }
  static inline pom128_t pom_byter8(pom128_t x) {
    pom128_t zero = {0, 0};
  #ifdef __LITTLE_ENDIAN__
    return vec_sld(zero, x, 8);
  #else
    return vec_sld(x, zero, 8);
  #endif
  }
  #define POM_BYTEL8(x)       pom_bytel8(x)
  #define POM_BYTER8(x)       pom_byter8(x)
  #define POM_ZERO()          ((pom128_t){0, 0})
  static inline unsigned long long pom_getlo64(pom128_t x) {
  #ifdef __LITTLE_ENDIAN__
    return x[0];
  #else
    return x[1];
  #endif
  }
  #define POM_GETLO64(x)      pom_getlo64(x)
#else
  #define POM_SCALAR 1
  typedef struct { unsigned long long lo, hi; } pom128_t;
  static inline pom128_t pom_add(pom128_t x, pom128_t y) {
    pom128_t r; r.lo = x.lo + y.lo; r.hi = x.hi + y.hi; return r;
  }
  static inline pom128_t pom_xor(pom128_t x, pom128_t y) {
    pom128_t r; r.lo = x.lo ^ y.lo; r.hi = x.hi ^ y.hi; return r;
  }
  static inline pom128_t pom_or(pom128_t x, pom128_t y) {
    pom128_t r; r.lo = x.lo | y.lo; r.hi = x.hi | y.hi; return r;
  }
  static inline pom128_t pom_shl64(pom128_t x, int n) {
    pom128_t r; r.lo = x.lo << n; r.hi = x.hi << n; return r;
  }
  static inline pom128_t pom_shr64(pom128_t x, int n) {
    pom128_t r; r.lo = x.lo >> n; r.hi = x.hi >> n; return r;
  }
  static inline pom128_t pom_bytel8(pom128_t x) {
    pom128_t r; r.hi = x.lo; r.lo = 0; return r;
  }
  static inline pom128_t pom_byter8(pom128_t x) {
    pom128_t r; r.lo = x.hi; r.hi = 0; return r;
  }
  #define POM_ADD(x, y)       pom_add((x), (y))
  #define POM_XOR(x, y)       pom_xor((x), (y))
  #define POM_OR(x, y)        pom_or((x), (y))
  #define POM_SHL64(x, n)     pom_shl64((x), (n))
  #define POM_SHR64(x, n)     pom_shr64((x), (n))
  #define POM_BYTEL8(x)       pom_bytel8(x)
  #define POM_BYTER8(x)       pom_byter8(x)
  static inline pom128_t pom_zero(void) {
    pom128_t r; r.lo = r.hi = 0; return r;
  }
  #define POM_ZERO()          pom_zero()
  static inline unsigned long long pom_getlo64(pom128_t x) { return x.lo; }
  #define POM_GETLO64(x)      pom_getlo64(x)
#endif

#define POM_ROTL(x, n) POM_XOR(POM_SHL64((x),(n)), POM_SHR64((x),(64-(n))))

#define POM_F0(i)  { \
    i0 = ((i) - 0*2)  & mask1; \
    i1 = ((i) - 2*2)  & mask1; \
    i2 = ((i) - 3*2)  & mask1; \
    i3 = ((i) - 7*2)  & mask1; \
    i4 = ((i) - 13*2) & mask1; \
    S[i0]   = POM_XOR(POM_ADD(POM_XOR(S[i1],   S[i2]),   S[i3]),   S[i4]); \
    S[i0+1] = POM_XOR(POM_ADD(POM_XOR(S[i1+1], S[i2+1]), S[i3+1]), S[i4+1]); \
    temp = S[i0]; \
    S[i0]   = POM_XOR(POM_BYTEL8(S[i0]),   POM_BYTER8(S[i0+1])); \
    S[i0+1] = POM_XOR(POM_BYTEL8(S[i0+1]), POM_BYTER8(temp)); \
    S[i0]   = POM_ROTL(S[i0],  17); \
    S[i0+1] = POM_ROTL(S[i0+1],17); \
}

#define POM_F(i)  { \
    i0 = ((i) - 0*2)  & mask1; \
    i1 = ((i) - 2*2)  & mask1; \
    i2 = ((i) - 3*2)  & mask1; \
    i3 = ((i) - 7*2)  & mask1; \
    i4 = ((i) - 13*2) & mask1; \
    S[i0]   = POM_ADD(S[i0],POM_XOR(POM_ADD(POM_XOR(S[i1],   S[i2]),   S[i3]),   S[i4])); \
    S[i0+1] = POM_ADD(S[i0+1],POM_XOR(POM_ADD(POM_XOR(S[i1+1], S[i2+1]), S[i3+1]), S[i4+1])); \
    temp = S[i0]; \
    S[i0]   = POM_XOR(POM_BYTEL8(S[i0]),   POM_BYTER8(S[i0+1])); \
    S[i0+1] = POM_XOR(POM_BYTEL8(S[i0+1]), POM_BYTER8(temp)); \
    S[i0]   = POM_ROTL(S[i0],  17); \
    S[i0+1] = POM_ROTL(S[i0+1],17); \
}

#define POM_G(i, random_number)  { \
    index_global = ((random_number >> 16) & mask) << 1; \
    for (j = 0; j < 64; j = j+2) { \
        POM_F(i+j); \
        index_global     = (index_global + 2) & mask1; \
        index_local      = (((i + j) >> 1) - 0x1000 + (random_number & 0x1fff)) & mask; \
        index_local      = index_local << 1; \
        S[i0]            = POM_ADD(S[i0],  POM_SHL64(S[index_local],1)); \
        S[i0+1]          = POM_ADD(S[i0+1],POM_SHL64(S[index_local+1],1)); \
        S[index_local]   = POM_ADD(S[index_local],   POM_SHL64(S[i0],2)); \
        S[index_local+1] = POM_ADD(S[index_local+1], POM_SHL64(S[i0+1],2)); \
        S[i0]            = POM_ADD(S[i0],  POM_SHL64(S[index_global],1)); \
        S[i0+1]          = POM_ADD(S[i0+1],POM_SHL64(S[index_global+1],1)); \
        S[index_global]  = POM_ADD(S[index_global],  POM_SHL64(S[i0],3)); \
        S[index_global+1]= POM_ADD(S[index_global+1],POM_SHL64(S[i0+1],3)); \
        random_number   += (random_number << 2); \
        random_number    = (random_number << 19) ^ (random_number >> 45) ^ 3141592653589793238ULL; \
    } \
}

#define POM_H(i, random_number)  { \
    index_global = ((random_number >> 16) & mask) << 1; \
    for (j = 0; j < 64; j = j+2) { \
        POM_F(i+j); \
        index_global     = (index_global + 2) & mask1; \
        index_local      = (((i + j) >> 1) - 0x1000 + (random_number & 0x1fff)) & mask; \
        index_local      = index_local << 1; \
        S[i0]            = POM_ADD(S[i0],  POM_SHL64(S[index_local],1)); \
        S[i0+1]          = POM_ADD(S[i0+1],POM_SHL64(S[index_local+1],1)); \
        S[index_local]   = POM_ADD(S[index_local],   POM_SHL64(S[i0],2)); \
        S[index_local+1] = POM_ADD(S[index_local+1], POM_SHL64(S[i0+1],2)); \
        S[i0]            = POM_ADD(S[i0],  POM_SHL64(S[index_global],1)); \
        S[i0+1]          = POM_ADD(S[i0+1],POM_SHL64(S[index_global+1],1)); \
        S[index_global]  = POM_ADD(S[index_global],  POM_SHL64(S[i0],3)); \
        S[index_global+1]= POM_ADD(S[index_global+1],POM_SHL64(S[i0+1],3)); \
        random_number  = POM_GETLO64(S[i3]); \
    } \
}

int pomelo_hash(void *out, size_t outlen, const void *in, size_t inlen,
        const void *salt, size_t saltlen,
        unsigned int t_cost, unsigned int m_cost)
{
  unsigned long long i, j;
  pom128_t temp;
  unsigned long long i0, i1, i2, i3, i4;
  pom128_t S[4096];
  unsigned long long random_number, index_global, index_local;
  unsigned long long state_size, mask, mask1;

  if (inlen > 256 || saltlen > 64 || outlen > 256 ||
      inlen < 0 || saltlen < 0 || outlen < 0) return 1;

  state_size = 1ULL << (13 + m_cost);
  mask  = (1ULL << (8 + m_cost)) - 1;
  mask1 = (1ULL << (9 + m_cost)) - 1;

  for (i = 0; i < inlen; i++)
    ((unsigned char *) S)[i] = ((unsigned char *) in)[i];
  for (i = 0; i < saltlen; i++)
    ((unsigned char *) S)[inlen + i] = ((unsigned char *) salt)[i];
  for (i = inlen + saltlen; i < 384; i++)
    ((unsigned char *) S)[i] = 0;
  ((unsigned char *) S)[384] = inlen & 0xff;
  ((unsigned char *) S)[385] = (inlen >> 8) & 0xff;
  ((unsigned char *) S)[386] = saltlen;
  ((unsigned char *) S)[387] = outlen & 0xff;
  ((unsigned char *) S)[388] = (outlen >> 8) & 0xff;
  ((unsigned char *) S)[389] = 0;
  ((unsigned char *) S)[390] = 0;
  ((unsigned char *) S)[391] = 0;
  ((unsigned char *) S)[392] = 1;
  ((unsigned char *) S)[393] = 1;
  for (i = 394; i < 416; i++)
    ((unsigned char *) S)[i] = ((unsigned char *) S)[i - 1] + ((unsigned char *) S)[i - 2];

  for (i = 13 * 2; i < (1ULL << (9 + m_cost)); i = i + 2)
    POM_F0(i);

  random_number = 123456789ULL;
  for (i = 0; i < (1ULL << (8 + m_cost + t_cost)); i = i + 64)
    POM_G(i, random_number);

  for (i = 1ULL << (8 + m_cost + t_cost);
       i < (1ULL << (9 + m_cost + t_cost)); i = i + 64)
    POM_H(i, random_number);

  for (i = 0; i < (1ULL << (9 + m_cost)); i = i + 2)
    POM_F(i);

  memcpy(out, ((unsigned char *) S) + state_size - outlen, outlen);
  return 0;
}

/* POMELO verify: salted, 64 hex chars (32 bytes output), t_cost=2, m_cost=3 */
static int hex2bin(const char *src, int srclen, unsigned char *dst);

static int verify_pomelo(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char expected[32], computed[32];
    const char *salt;
    int saltlen;

    /* Format: 64hex:salt */
    if (hashlen < 65 || hashstr[64] != ':') return 0;
    if (hex2bin(hashstr, 64, expected) != 32) return 0;
    salt = hashstr + 65;
    saltlen = hashlen - 65;

    if (pomelo_hash(computed, 32, pass, passlen, salt, saltlen, 2, 3) != 0)
        return 0;
    return memcmp(computed, expected, 32) == 0;
}

/* ---- OpenSSL base compute functions ---- */

static void compute_md5(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    (void)salt; (void)saltlen;
    rhash_msg(RHASH_MD5, pass, passlen, dest);
}

static void compute_md4(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    (void)salt; (void)saltlen;
    rhash_msg(RHASH_MD4, pass, passlen, dest);
}

/* Thread-local iconv handles for UTF-16LE/BE conversion */
static __thread iconv_t iconv_utf16le = (iconv_t)-1;
static __thread iconv_t iconv_utf16be = (iconv_t)-1;

/* iconv-based UTF-8 → UTF-16LE conversion. Returns byte count of UTF-16LE output.
 * Uses //IGNORE to silently discard invalid UTF-8 sequences. */
static int utf8_to_utf16le(const unsigned char *src, int srclen,
    unsigned char *dst, int dstmax)
{
    char *inbuf, *outbuf;
    size_t inleft, outleft;

    if (iconv_utf16le == (iconv_t)-1) {
        iconv_utf16le = iconv_open("UTF-16LE//IGNORE", "UTF-8");
        if (iconv_utf16le == (iconv_t)-1) return 0;
    }

    inbuf = (char *)src;
    inleft = srclen;
    outbuf = (char *)dst;
    outleft = dstmax;

    iconv(iconv_utf16le, &inbuf, &inleft, &outbuf, &outleft);
    iconv(iconv_utf16le, NULL, NULL, NULL, NULL);
    return dstmax - (int)outleft;
}

/* iconv-based UTF-8 → UTF-16BE conversion. Returns byte count of UTF-16BE output. */
static int utf8_to_utf16be(const unsigned char *src, int srclen,
    unsigned char *dst, int dstmax)
{
    char *inbuf, *outbuf;
    size_t inleft, outleft, ret;

    if (iconv_utf16be == (iconv_t)-1) {
        /* //IGNORE matches mdxfind: a password that is not valid UTF-8
         * is converted with the bad sequences skipped rather than the
         * conversion failing, which is what mdxfind hashed. */
        iconv_utf16be = iconv_open("UTF-16BE//IGNORE", "UTF-8");
        if (iconv_utf16be == (iconv_t)-1) return 0;
    }

    inbuf = (char *)src;
    inleft = srclen;
    outbuf = (char *)dst;
    outleft = dstmax;

    ret = iconv(iconv_utf16be, &inbuf, &inleft, &outbuf, &outleft);
    if (ret == (size_t)-1 && outleft == (size_t)dstmax) {
        iconv(iconv_utf16be, NULL, NULL, NULL, NULL);
        return 0;
    }
    iconv(iconv_utf16be, NULL, NULL, NULL, NULL);
    return dstmax - (int)outleft;
}

/* mdxfind's to_utf16le is a naive byte expansion -- each input byte becomes
 * that byte followed by a NUL -- not a UTF-8 to UTF-16LE conversion.  Plain
 * NTLM goes through iconv there, but DCC2 and its relatives use this, so they
 * disagree with the iconv form for every non-ASCII password.  mdxfind is
 * authoritative, so the types that use it get this. */
static int latin1_to_utf16le(const unsigned char *src, int srclen,
    unsigned char *dst, int dstmax)
{
    int i;
    if (srclen * 2 > dstmax) srclen = dstmax / 2;
    for (i = 0; i < srclen; i++) { dst[i * 2] = src[i]; dst[i * 2 + 1] = 0; }
    return srclen * 2;
}

static void compute_ntlm_latin1(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *utf16 = WS->u16a;
    int u16len;
    (void)salt; (void)saltlen;
    u16len = latin1_to_utf16le(pass, passlen, utf16, WS_U16_SIZE);
    rhash_msg(RHASH_MD4, utf16, u16len, dest);
}

static void compute_ntlm(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *utf16 = WS->u16a;
    int u16len;
    (void)salt; (void)saltlen;
    u16len = utf8_to_utf16le(pass, passlen, utf16, WS_U16_SIZE);
    rhash_msg(RHASH_MD4, utf16, u16len, dest);
}

/* UTF-16LE wrapper types: hash(utf16le(pass)) */
#define MAKE_UTF16LE(fname, hash_fn) \
static void compute_##fname(const unsigned char *pass, int passlen, \
    const unsigned char *salt, int saltlen, unsigned char *dest) \
{ \
    unsigned char *_u16 = WS->u16a; \
    int _u16len; \
    (void)salt; (void)saltlen; \
    _u16len = utf8_to_utf16le(pass, passlen, _u16, WS_U16_SIZE); \
    hash_fn(_u16, _u16len, NULL, 0, dest); \
}

/* MD4UTF16 = NTLM (same computation, different type name) */
/* (shares compute_ntlm) */

static void compute_sha1(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    (void)salt; (void)saltlen;
    SHA1(pass, passlen, dest);
}

