/* Forward declarations for mysql3 functions used below */
static void compute_mysql3(const unsigned char *, int, const unsigned char *, int, unsigned char *);
static int mysql3_hex(const unsigned char *, int, char *);

/* MD5SQL3SQL5MD5MD5: mdxfind does MD5(pass)→MD5→SHA1→SHA1→"*"+hexUC→mysql3→MD5
 * = MD5(mysql3("*" + hexUC(SHA1(SHA1(hex(MD5(hex(MD5(pass))))))))) */
static void compute_md5sql3sql5md5md5(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    unsigned char *sha1a = (unsigned char *)WS->ctx2;
    unsigned char *sha1b = (unsigned char *)WS->ctx3;
    unsigned char *sql3bin = (unsigned char *)WS->ctx4;
    char *hx = (char *)WS->gp1;
    char *sql5str = (char *)WS->gp2;
    char *sql3hex = (char *)WS->gp3;
    (void)salt; (void)saltlen;
    /* MD5(pass) → hex → MD5 → hex */
    rhash_msg(RHASH_MD5, pass, passlen, md5);
    prmd5(md5, hx, 32);
    rhash_msg(RHASH_MD5, (unsigned char *)hx, 32, md5);
    prmd5(md5, hx, 32);
    /* SHA1(hex, 32) → SHA1(raw, 20) */
    SHA1((unsigned char *)hx, 32, sha1a);
    SHA1(sha1a, 20, sha1b);
    /* "*" + hexUC(sha1b) → 41 chars */
    sql5str[0] = '*';
    prmd5UC(sha1b, sql5str + 1, 40);
    sql5str[41] = 0;
    /* mysql3(sql5str, 41) → 8 bytes binary, then hex → 16 chars */
    compute_mysql3((unsigned char *)sql5str, 41, NULL, 0, sql3bin);
    mysql3_hex((unsigned char *)sql5str, 41, sql3hex);
    /* MD5(sql3hex, 16) */
    rhash_msg(RHASH_MD5, (unsigned char *)sql3hex, 16, dest);
}

/* MD5-6xMD5: MD5 iterated 7 times total */
/* MD5-6xMD5: MD5(hex(MD5(pass)) repeated 6 times) */
static void compute_md5_6xmd5(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *md5bin = (unsigned char *)WS->ctx1;
    char *buf = (char *)WS->gp1;
    int i;
    (void)salt; (void)saltlen;
    rhash_msg(RHASH_MD5, pass, passlen, md5bin);
    prmd5(md5bin, buf, 32);
    for (i = 1; i < 6; i++)
        memcpy(buf + i * 32, buf, 32);
    rhash_msg(RHASH_MD5, (unsigned char *)buf, 192, dest);
}

/* MD5-5xMD5: MD5(hex(MD5(pass)) repeated 5 times) */
static void compute_md5_5xmd5(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *md5bin = (unsigned char *)WS->ctx1;
    char *buf = (char *)WS->gp1;
    int i;
    (void)salt; (void)saltlen;
    rhash_msg(RHASH_MD5, pass, passlen, md5bin);
    prmd5(md5bin, buf, 32);
    for (i = 1; i < 5; i++)
        memcpy(buf + i * 32, buf, 32);
    rhash_msg(RHASH_MD5, (unsigned char *)buf, 160, dest);
}

/* SHA1SQL5-32: SHA1(hex(SQL5(pass))[0:32]) */
static void compute_sha1sql5_32(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *sha1bin = (unsigned char *)WS->ctx1;
    char *hexstr = (char *)WS->gp1;
    int i;
    (void)salt; (void)saltlen;
    /* hx.8 e660: sha1(cut(upper(sha1(sha1_bin(pass))), 0, 32)). The SQL5
       digest is UPPERCASE hex -- this used hextab_lc. */
    SHA1(pass, passlen, sha1bin);
    SHA1(sha1bin, 20, sha1bin);
    for (i = 0; i < 20; i++) {
        hexstr[i * 2]     = hextab_uc[(sha1bin[i] >> 4) & 0xf];
        hexstr[i * 2 + 1] = hextab_uc[sha1bin[i] & 0xf];
    }
    SHA1((unsigned char *)hexstr, 32, dest);
}

/* SHA1MD5SQL5 (e712) and SHA1MD5MD5SQL5 (e713).
 *
 * These were chains { S_SQL5, S_MD5, S_SHA1 } and { S_SQL5, S_MD5, S_MD5,
 * S_SHA1 }, but the chain machinery feeds the previous step's LOWERCASE hex
 * onward and cannot prepend a literal. The real SQL5 form that MySQL stores is
 * "*" followed by the UPPERCASE digest, and both types hash that string --
 * hx.8 e712 is sha1(md5("*" . upper(sha1(sha1_bin(pass))))). Hand-written
 * here so the prefix and the case are both right. Confirmed against live
 * cracks and against mdxfind's own values. */
static void compute_sha1md5sql5(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char h[20], m[16];
    char buf[42], mx[33];
    (void)salt; (void)saltlen;
    SHA1(pass, passlen, h);
    SHA1(h, 20, h);
    buf[0] = '*';
    bin2hexUC(h, 20, buf + 1);
    rhash_msg(RHASH_MD5, (unsigned char *)buf, 41, m);
    bin2hex(m, 16, mx);
    SHA1((unsigned char *)mx, 32, dest);
}

static void compute_sha1md5md5sql5(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char h[20], m[16];
    char buf[42], mx[33];
    (void)salt; (void)saltlen;
    SHA1(pass, passlen, h);
    SHA1(h, 20, h);
    buf[0] = '*';
    bin2hexUC(h, 20, buf + 1);
    rhash_msg(RHASH_MD5, (unsigned char *)buf, 41, m);
    bin2hex(m, 16, mx);
    rhash_msg(RHASH_MD5, (unsigned char *)mx, 32, m);
    bin2hex(m, 16, mx);
    SHA1((unsigned char *)mx, 32, dest);
}

/* MD5DECBASE64MD5BASE64MD5: rhash_msg(RHASH_MD5, dec_base64(hex(MD5(base64(hex(MD5(pass))))))) */
static void compute_md5decbase64md5base64md5(const unsigned char *pass, int passlen, const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *md5bin = (unsigned char *)WS->ctx1;
    unsigned char *md5bin2 = (unsigned char *)WS->ctx2;
    unsigned char *decbuf = (unsigned char *)WS->gp1;
    char *hexstr = (char *)WS->gp2;
    char *b64 = (char *)WS->gp3;
    char *hexstr2 = (char *)WS->gp4;
    int blen, dlen, i;
    (void)salt; (void)saltlen;
    /* rhash_msg(RHASH_MD5, pass) */
    rhash_msg(RHASH_MD5, pass, passlen, md5bin);
    for (i = 0; i < 16; i++) {
        hexstr[i * 2]     = hextab_lc[(md5bin[i] >> 4) & 0xf];
        hexstr[i * 2 + 1] = hextab_lc[md5bin[i] & 0xf];
    }
    /* base64(hex(rhash_msg(RHASH_MD5, pass))) */
    blen = base64_encode((unsigned char *)hexstr, 32, b64, WS_GP_SIZE);
    /* rhash_msg(RHASH_MD5, base64(...)) */
    rhash_msg(RHASH_MD5, (unsigned char *)b64, blen, md5bin2);
    for (i = 0; i < 16; i++) {
        hexstr2[i * 2]     = hextab_lc[(md5bin2[i] >> 4) & 0xf];
        hexstr2[i * 2 + 1] = hextab_lc[md5bin2[i] & 0xf];
    }
    /* base64_decode(hex(rhash_msg(RHASH_MD5, ...))) */
    dlen = base64_decode(hexstr2, 32, decbuf, WS_GP_SIZE);
    if (dlen < 0) dlen = 0;
    /* rhash_msg(RHASH_MD5, decoded) */
    rhash_msg(RHASH_MD5, decbuf, dlen, dest);
}

/* SHA1revBASE64: SHA1(reverse(base64(pass))) */
static void compute_sha1revbase64(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    char *b64 = (char *)WS->gp1;
    int blen;
    (void)salt; (void)saltlen;
    blen = base64_encode(pass, passlen, b64, WS_GP_SIZE);
    reverse_str(b64, blen);
    SHA1((unsigned char *)b64, blen, dest);
}

/* SHA1revBASE64x: SHA1(reverse(base64(pass))) — base64 with padding, salt present */
static void compute_sha1revbase64x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    char *b64 = (char *)WS->gp1;
    int blen;
    (void)salt; (void)saltlen;
    blen = base64_encode(pass, passlen, b64, WS_GP_SIZE);
    reverse_str(b64, blen);
    SHA1((unsigned char *)b64, blen, dest);
}

/* ---- x-type compute functions: two-level iteration ----
 * Outer iteration: controlled by salt (parsed as integer).
 * Inner iteration: handled by generic iteration loops in verify_item.
 * The salt field carries the outer iteration count (e.g., "1", "2", "3").
 */

/* Parse salt bytes as a decimal integer; return 1 if invalid/absent */
static int salt_to_int(const unsigned char *salt, int saltlen)
{
    int val = 0, i;
    if (!salt || saltlen <= 0) return 1;
    for (i = 0; i < saltlen; i++) {
        if (salt[i] < '0' || salt[i] > '9') return 1;
        val = val * 10 + (salt[i] - '0');
    }
    if (val < 1) return 1;
    if (val > Maxiter) return Maxiter;
    return val;
}

/* SHA1MD5x: outer=iterate MD5, inner=iterate SHA1.
 * x01 salt=N: SHA1(hex(MD5^N(pass))) */
static void compute_sha1md5x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        rhash_msg(RHASH_MD5, cur, curlen, bin);
        prmd5(bin, hex, 32);
        cur = (const unsigned char *)hex;
        curlen = 32;
    }
    SHA1(cur, curlen, dest);
}

/* SHA1SHA256x: outer=iterate SHA256(lc hex), inner=iterate SHA1.
 * x01 salt=N: SHA1(hex(SHA256^N(pass))) */
static void compute_sha1sha256x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        SHA256(cur, curlen, bin);
        prmd5(bin, hex, 64);
        cur = (const unsigned char *)hex;
        curlen = 64;
    }
    SHA1(cur, curlen, dest);
}

/* SHA1SHA256UCx: outer=iterate SHA256(UC hex), inner=iterate SHA1.
 * x01 salt=N: SHA1(hexUC(SHA256^N(pass))) */
static void compute_sha1sha256ucx(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        SHA256(cur, curlen, bin);
        prmd5UC(bin, hex, 64);
        cur = (const unsigned char *)hex;
        curlen = 64;
    }
    SHA1(cur, curlen, dest);
}

/* SHA1MD5UCx: outer=iterate MD5(UC hex), inner=iterate SHA1.
 * x01 salt=N: SHA1(hexUC(MD5^N(pass))) */
static void compute_sha1md5ucx(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        rhash_msg(RHASH_MD5, cur, curlen, bin);
        prmd5UC(bin, hex, 32);
        cur = (const unsigned char *)hex;
        curlen = 32;
    }
    SHA1(cur, curlen, dest);
}

/* SHA1MD5MD5UCx: outer=iterate MD5(UC hex), then MD5(lc hex) + SHA1.
 * x01 salt=N: SHA1(hex(MD5(hexUC(MD5^N(pass))))) */
static void compute_sha1md5md5ucx(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    char *hex2 = (char *)WS->gp2;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        rhash_msg(RHASH_MD5, cur, curlen, bin);
        prmd5UC(bin, hex, 32);
        cur = (const unsigned char *)hex;
        curlen = 32;
    }
    /* MD5(UC hex) -> hex -> SHA1(hex) */
    rhash_msg(RHASH_MD5, cur, curlen, bin);
    prmd5(bin, hex2, 32);
    SHA1((unsigned char *)hex2, 32, dest);
}

/* SHA1revBASE64x: outer=iterate base64 + reverse, inner=iterate SHA1.
 * x01 salt=N: SHA1(reverse(base64^N(pass))) */
static void compute_sha1revbase64x_outer(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    char *b64 = (char *)WS->gp3, *rev = (char *)WS->gp4;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        int blen = base64_encode(cur, curlen, b64, MAXLINE);
        if (blen <= 0 || blen >= MAXLINE) { memset(dest, 0, 20); return; }
        /* reverse into rev */
        {
            int j;
            for (j = 0; j < blen; j++) rev[blen - 1 - j] = b64[j];
        }
        rev[blen] = 0;
        cur = (const unsigned char *)rev;
        curlen = blen;
    }
    SHA1(cur, curlen, dest);
}

/* MD4UTF16MD5x: outer=iterate MD5(lc hex), inner=iterate NTLM.
 * x01 salt=N: NTLM(hex(MD5^N(pass))) */
/* The "x" family carries its chain length in the salt field: mdxfind loops
 * i = 1..Maxniter, re-hashing the hex of the previous round, and reports i.
 * These three computed only the i=1 form, so they verified one fifth of the
 * fixture and failed every longer chain. */
/* RADMIN2 pads its input to 100 bytes with NULs before the final md5, and the
 * iteration re-applies that whole step: the chain is md5(pad(hex, 100)), not
 * plain md5 over the hex.  The chain-registered RADMIN2 variants get this from
 * their chain definition, but RADMIN2BASE64, RADMIN2SQL3 and RADMIN2SQL5-40
 * are plain registrations with nothing, so they resolved at base depth only. */
/* MYSQL5MD5 (e539) falls into the SQL5 loop in mdxfind, whose chain state is
 * the UPPERCASE hex of the inner sha1 -- a value that is never emitted.  The
 * emitted digest is sha1 of that inner sha1, so the next depth cannot be
 * derived from the previous emitted value at all and has to be recomputed from
 * the password.  Nothing generic could iterate this, so it sat at base depth. */
static int sql5_engine(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen, int md5first)
{
    unsigned char *inner = (unsigned char *)WS->ctx1;
    unsigned char *bin   = (unsigned char *)WS->ctx2;
    char *cur     = (char *)WS->gp1;
    char *emitted = (char *)WS->gp2;
    int x, curlen;

    if (hashlen < 40) return 0;
    if (md5first) {
        rhash_msg(RHASH_MD5, pass, passlen, bin);
        prmd5(bin, cur, 32);
        curlen = 32;
    } else {
        if (passlen > MAXLINE) return 0;
        memcpy(cur, pass, passlen);
        curlen = passlen;
    }
    for (x = 1; x <= Maxiter; x++) {
        SHA1((const unsigned char *)cur, curlen, inner);
        SHA1(inner, 20, bin);
        prmd5(bin, emitted, 40);
        if (strncasecmp(emitted, hashstr, 40) == 0) { WS->verify_iter = x; return 1; }
        prmd5UC(inner, cur, 40);
        curlen = 40;
    }
    return 0;
}

static int verify_mysql5md5(const char *h, int hl, const unsigned char *p, int pl)
{ return sql5_engine(h, hl, p, pl, 1); }
static int verify_sql5(const char *h, int hl, const unsigned char *p, int pl)
{ return sql5_engine(h, hl, p, pl, 0); }

/* NULL (e425) is a passthrough diagnostic: the candidate is copied into a
 * zeroed 16-byte buffer and reported as-is, and each further depth overwrites
 * byte 0 with the depth number.  The compute produced only the base form. */
static int verify_null(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *buf = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    int x, n = passlen < 16 ? passlen : 16;

    if (hashlen != 32) return 0;
    memset(buf, 0, 16);
    memcpy(buf, pass, n);
    for (x = 1; x <= Maxiter; x++) {
        prmd5(buf, hex, 32);
        if (strncasecmp(hex, hashstr, 32) == 0) { WS->verify_iter = x; return 1; }
        buf[0] = (unsigned char)x;
    }
    return 0;
}

/* SHA1MD5MD5PASS (e663) emits two digests per candidate and iterates both with
 * sha1 over the hex.  The second shape hashes 33 bytes of a 32-character hex
 * buffer, so it includes the NUL that prmd5 writes at out[len]; that is
 * deterministic but is not what the expression alone suggests. */
static int verify_sha1md5md5pass(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hx  = (char *)WS->gp1;
    char *buf = (char *)WS->gp2;
    char *run = (char *)WS->gp3;
    int sh, iter, n;

    if (hashlen < 40) return 0;
    if (passlen > MAXLINE - 64) return 0;
    rhash_msg(RHASH_MD5, pass, passlen, bin);
    prmd5(bin, hx, 32);

    for (sh = 0; sh < 2; sh++) {
        n = 32;
        memcpy(buf, hx, 32);
        if (sh == 1) buf[n++] = ':';
        memcpy(buf + n, pass, passlen);
        rhash_msg(RHASH_MD5, (unsigned char *)buf, n + passlen, bin);
        prmd5(bin, run, 32);
        run[32] = 0;
        SHA1((const unsigned char *)run, sh == 0 ? 32 : 33, bin);
        prmd5(bin, run, 40);
        for (iter = 1; iter <= Maxiter; iter++) {
            if (strncasecmp(run, hashstr, 40) == 0) { WS->verify_iter = iter; return 1; }
            SHA1((const unsigned char *)run, 40, bin);
            prmd5(bin, run, 40);
        }
    }
    return 0;
}

/* SHA1lsb32 (e398): each round sha1s the running value, zeroes the first four
 * bytes of the digest, and reports only the first 16 bytes as 32 hex -- but
 * chains on the FULL 40-character hex.  The chain input is therefore wider
 * than anything reported, so the next depth cannot be derived from the
 * previous line and has to be recomputed. */
static int verify_sha1lsb32(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *d = (unsigned char *)WS->ctx1;
    char *cur = (char *)WS->gp1;
    char *hex = (char *)WS->gp2;
    int x, curlen;

    if (hashlen != 32) return 0;
    if (passlen > MAXLINE) return 0;
    memcpy(cur, pass, passlen);
    curlen = passlen;
    for (x = 1; x <= Maxiter; x++) {
        SHA1((const unsigned char *)cur, curlen, d);
        d[0] = d[1] = d[2] = d[3] = 0;
        prmd5(d, hex, 40);
        if (strncasecmp(hex, hashstr, 32) == 0) { WS->verify_iter = x; return 1; }
        memcpy(cur, hex, 40);
        curlen = 40;
    }
    return 0;
}

/* SHA1HAV128 (e640): reports the full 40-character sha1 hex but chains on only
 * the first 32 characters of it, because the iteration writes the digest with
 * a width of 32 rather than 40.  Deterministic, so it is reproduced here. */
static int verify_sha1hav128(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *h = (unsigned char *)WS->ctx1;
    unsigned char *d = (unsigned char *)WS->ctx2;
    char *hx = (char *)WS->gp1;
    int x;

    if (hashlen != 40) return 0;
    compute_hav128_3(pass, passlen, NULL, 0, h);
    prmd5(h, hx, 32);
    SHA1((const unsigned char *)hx, 32, d);
    for (x = 1; x <= Maxiter; x++) {
        prmd5(d, hx, 40);
        if (strncasecmp(hx, hashstr, 40) == 0) { WS->verify_iter = x; return 1; }
        prmd5(d, hx, 32);
        SHA1((const unsigned char *)hx, 32, d);
    }
    return 0;
}

/* SHA1-SHA512PASSSHA512SALT (e637): sha1 over the 128-character sha512 hex of
 * the candidate followed by the same of the salt.  The iteration writes the
 * 40-character digest hex but hashes only the first 32 of it, so the chain
 * runs on a truncated digest -- the same shape as SHA1HAV128.  Deterministic,
 * so it is reproduced. */
static int verify_sha1_sha512passsha512salt(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *d = (unsigned char *)WS->ctx1;
    char *buf = (char *)WS->gp1;
    char *hx  = (char *)WS->gp2;
    const unsigned char *salt;
    const char *colon;
    int saltlen, x, dec;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon || colon - hashstr != 40) return 0;
    saltlen = hashlen - 41;
    if (saltlen < 0 || saltlen > 200) return 0;
    salt = (const unsigned char *)colon + 1;
    dec = decode_hex_password(colon + 1, saltlen, (unsigned char *)WS->gp3, MAXLINE);
    if (dec >= 0) { salt = (const unsigned char *)WS->gp3; saltlen = dec; }

    SHA512(pass, passlen, d);
    prmd5(d, buf, 128);
    SHA512(salt, saltlen, d);
    prmd5(d, buf + 128, 128);
    SHA1((const unsigned char *)buf, 256, d);
    for (x = 1; x <= Maxiter; x++) {
        prmd5(d, hx, 40);
        if (strncasecmp(hx, hashstr, 40) == 0) { WS->verify_iter = x; return 1; }
        SHA1((const unsigned char *)hx, 32, d);
    }
    return 0;
}

/* MD5SHA1MD5x (e359): the salt field carries the md5 chain length.  Build
 * md5^q of the candidate as hex, sha1 that, take the 40-character hex of the
 * result and md5 it; then iterate md5 over the 32-character hex. */
static int verify_md5sha1md5x(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    unsigned char *sh  = (unsigned char *)WS->ctx2;
    char *hx  = (char *)WS->gp1;
    char *run = (char *)WS->gp2;
    const char *colon;
    int q, i, x;

    if (hashlen < 32) return 0;
    colon = memchr(hashstr, ':', hashlen);
    if (!colon || colon - hashstr != 32) return 0;
    q = atoi(colon + 1);
    if (q < 1 || q > 64) return 0;

    rhash_msg(RHASH_MD5, pass, passlen, bin);
    prmd5(bin, hx, 32);
    for (i = 1; i < q; i++) {
        rhash_msg(RHASH_MD5, (unsigned char *)hx, 32, bin);
        prmd5(bin, hx, 32);
    }
    SHA1((const unsigned char *)hx, 32, sh);
    prmd5(sh, run, 40);
    rhash_msg(RHASH_MD5, (unsigned char *)run, 40, bin);
    for (x = 1; x <= Maxiter; x++) {
        prmd5(bin, run, 32);
        if (strncasecmp(run, hashstr, 32) == 0) { WS->verify_iter = x; return 1; }
        rhash_msg(RHASH_MD5, (unsigned char *)run, 32, bin);
    }
    return 0;
}

/* MD5RAWUC (e383): md5 of the raw md5 bytes, then each round is md5 over the
 * UPPERCASE hex of the previous value, and the first value reported is already
 * one round in -- mdxfind enters its loop with x = 2.  So no depth is reported
 * for the starting value, and the chain runs on uppercase hex rather than the
 * usual lowercase. */
static int md5uc_engine(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen, int via_hex)
{
    unsigned char *v = (unsigned char *)WS->ctx1;
    char *hx = (char *)WS->gp1;
    int x;

    if (hashlen != 32) return 0;
    rhash_msg(RHASH_MD5, pass, passlen, v);
    if (via_hex) {
        /* MD5UCMD5 feeds the HEX of the first digest into the second md5;
         * MD5RAWUC feeds the raw sixteen bytes. */
        prmd5(v, hx, 32);
        rhash_msg(RHASH_MD5, (unsigned char *)hx, 32, v);
    } else {
        rhash_msg(RHASH_MD5, v, 16, v);
    }
    for (x = 2; x <= Maxiter; x++) {
        prmd5UC(v, hx, 32);
        rhash_msg(RHASH_MD5, (unsigned char *)hx, 32, v);
        prmd5(v, hx, 32);
        if (strncasecmp(hx, hashstr, 32) == 0) { WS->verify_iter = x; return 1; }
    }
    return 0;
}

static int verify_md5rawuc(const char *h, int hl, const unsigned char *p, int pl)
{ return md5uc_engine(h, hl, p, pl, 0); }
static int verify_md5ucmd5(const char *h, int hl, const unsigned char *p, int pl)
{ return md5uc_engine(h, hl, p, pl, 1); }

static void compute_md5_pad100(const unsigned char *in, int inlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *buf = (unsigned char *)WS->ctx6;
    (void)salt; (void)saltlen;
    if (inlen > 100) inlen = 100;
    memcpy(buf, in, inlen);
    memset(buf + inlen, 0, 100 - inlen);
    rhash_msg(RHASH_MD5, buf, 100, dest);
}

static void compute_md4utf16sha256x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    if (outer < 1) outer = 1;
    for (i = 0; i < outer; i++) {
        SHA256(cur, curlen, bin);
        prmd5(bin, hex, 64);
        cur = (const unsigned char *)hex;
        curlen = 64;
    }
    compute_ntlm(cur, curlen, NULL, 0, dest);
}

static void compute_md5sha1x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    if (outer < 1) outer = 1;
    for (i = 0; i < outer; i++) {
        SHA1(cur, curlen, bin);
        prmd5(bin, hex, 40);
        cur = (const unsigned char *)hex;
        curlen = 40;
    }
    rhash_msg(RHASH_MD5, cur, curlen, dest);
}

/* One lowercase sha256-hex pre-step, then the loop capitalises each round. */
static void compute_sha1sha256ucxsha256(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    if (outer < 1) outer = 1;
    SHA256(cur, curlen, bin);
    prmd5(bin, hex, 64);
    cur = (const unsigned char *)hex; curlen = 64;
    for (i = 0; i < outer; i++) {
        SHA256(cur, curlen, bin);
        prmd5UC(bin, hex, 64);
        cur = (const unsigned char *)hex;
        curlen = 64;
    }
    SHA1(cur, curlen, dest);
}

static void compute_md4utf16md5x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        rhash_msg(RHASH_MD5, cur, curlen, bin);
        prmd5(bin, hex, 32);
        cur = (const unsigned char *)hex;
        curlen = 32;
    }
    compute_ntlm(cur, curlen, NULL, 0, dest);
}

/* MD4UTF16SHA1x: outer=iterate SHA1(lc hex), inner=iterate NTLM.
 * x01 salt=N: NTLM(hex(SHA1^N(pass))) */
static void compute_md4utf16sha1x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    unsigned char *bin = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        SHA1(cur, curlen, bin);
        prmd5(bin, hex, 40);
        cur = (const unsigned char *)hex;
        curlen = 40;
    }
    compute_ntlm(cur, curlen, NULL, 0, dest);
}

/* MD4UTF16revBASE64x: outer=iterate base64 + reverse, inner=iterate NTLM.
 * x01 salt=N: NTLM(reverse(base64^N(pass))) */
static void compute_md4utf16revbase64x(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, unsigned char *dest)
{
    char *b64 = (char *)WS->gp3, *rev = (char *)WS->gp4;
    const unsigned char *cur = pass;
    int curlen = passlen, i;
    int outer = salt_to_int(salt, saltlen);
    for (i = 0; i < outer; i++) {
        int blen = base64_encode(cur, curlen, b64, MAXLINE);
        if (blen <= 0 || blen >= MAXLINE) { memset(dest, 0, 16); return; }
        {
            int j;
            for (j = 0; j < blen; j++) rev[blen - 1 - j] = b64[j];
        }
        rev[blen] = 0;
        cur = (const unsigned char *)rev;
        curlen = blen;
    }
    compute_ntlm(cur, curlen, NULL, 0, dest);
}

/* SHA1BASE64CUSTBASE64MD5: SHA1(base64_custom(base64(raw(rhash_msg(RHASH_MD5, pass))))) */
/* "CUST" likely means custom base64 alphabet — need to verify */
/* SHA1BASE64CUSTBASE64MD5 (e770): four variants over an LDAP-style "{MD5}"
   password field.  Despite the CUST in the name the base64 alphabet is
   standard RFC 4648.  The field is built two ways -- the binary MD5 base64'd
   with a trailing newline, or the MD5 hex string -- and each is base64'd again
   and SHA-1'd at both full length and trimmed.  The two families trim
   differently: the binary form drops exactly one trailing character, the hex
   form strips the whole '=' pad.  Live corpus hashes are variant 1. */
static int verify_sha1base64custbase64md5(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char md5bin[16], sha1[20];
    char inner[64], outer[128], hexhash[41];
    int ilen, olen, tlen, v;

    if (hashlen != 40) return 0;
    rhash_msg(RHASH_MD5, pass, passlen, md5bin);

    for (v = 0; v < 2; v++) {
        memcpy(inner, "{MD5}", 5);
        if (v == 0) {
            ilen = 5 + base64_encode(md5bin, 16, inner + 5, sizeof(inner) - 6);
            inner[ilen++] = '\n';
        } else {
            prmd5(md5bin, inner + 5, 32);
            ilen = 5 + 32;
        }
        olen = base64_encode((unsigned char *)inner, ilen, outer, sizeof(outer));

        SHA1((unsigned char *)outer, olen, sha1);
        prmd5(sha1, hexhash, 40);
        if (hex_iter_match(hexhash, hashstr, ITER_SHA1)) return 1;

        if (v == 0) {
            tlen = olen - 1;                 /* drop one trailing character */
        } else {
            tlen = olen;                     /* strip the '=' padding */
            while (tlen && outer[tlen - 1] == '=') tlen--;
        }
        if (tlen > 0 && tlen != olen) {
            SHA1((unsigned char *)outer, tlen, sha1);
            prmd5(sha1, hexhash, 40);
            if (hex_iter_match(hexhash, hashstr, ITER_SHA1)) return 1;
        }
    }
    return 0;
}

/* ---- Batch 3: HEXSALT types ---- */

/* HEXSALT inner: MD5(salt + pass), result hex'd into buf[0..31].
 * mode 0: buf = hex + ":" + salt (colon separator)
 * mode 1: buf = hex + salt (no separator)
 * mode 2: buf = hex + ":" + salt + ":" (colon both sides)
 * Returns total length in buf. */
static int hexsalt_inner(const unsigned char *pass, int passlen,
    const unsigned char *salt, int saltlen, char *buf, int mode)
{
    unsigned char md5bin[16];
    int i, blen;
    rhash ctx;
    ctx = rhash_init(RHASH_MD5);
    rhash_update(ctx, salt, saltlen);
    rhash_update(ctx, pass, passlen);
    rhash_final(ctx, md5bin); rhash_free(ctx);
    for (i = 0; i < 16; i++) {
        buf[i * 2]     = hextab_lc[(md5bin[i] >> 4) & 0xf];
        buf[i * 2 + 1] = hextab_lc[md5bin[i] & 0xf];
    }
    blen = 32;
    if (mode != 1) buf[blen++] = ':';
    memcpy(buf + blen, salt, saltlen);
    blen += saltlen;
    if (mode == 2) buf[blen++] = ':';
    return blen;
}

