    prmd5(md, hex, 32);
    SHA1((unsigned char *)hex, 32, h); SHA1(h, 20, h);
    buf[0] = '*'; prmd5UC(h, buf + 1, 40);
    SHA1((unsigned char *)buf, 41, dest);
