static void lotus_mix(unsigned char *state) {
    int p = 0, i, k;
    for (i = 0; i < 18; i++) {
        for (k = 0; k < 48; k++) {
            p = (p + (48 - k)) & 0xff;
            p = state[k] ^ lotus_magic_table[p];
            state[k] = p;
        }
    }
}

static void lotus_transform_password(const unsigned char *block, unsigned char *checksum) {
    unsigned char t = checksum[15];
    int i;
    for (i = 0; i < 16; i++) {
        t = checksum[i] ^ lotus_magic_table[block[i] ^ t];
        checksum[i] = t;
    }
}

static void domino5_transform(const unsigned char *input, int inlen, unsigned char *output) {
    unsigned char state[48], padded[512], checksum[16];
    int padlen, nblocks, i, j;

    padlen = 16 - (inlen % 16);
    if (padlen == 0) padlen = 16;
    if (inlen + padlen > (int)sizeof(padded)) return;
    memcpy(padded, input, inlen);
    memset(padded + inlen, padlen, padlen);
    nblocks = (inlen + padlen) / 16;

    memset(state, 0, 48);
    memset(checksum, 0, 16);

    for (i = 0; i < nblocks; i++) {
        unsigned char *block = padded + i * 16;
        for (j = 0; j < 16; j++) {
            state[16 + j] = block[j];
            state[32 + j] = block[j] ^ state[j];
        }
        lotus_mix(state);
        lotus_transform_password(block, checksum);
    }

    for (j = 0; j < 16; j++) {
        state[16 + j] = checksum[j];
        state[32 + j] = checksum[j] ^ state[j];
    }
    lotus_mix(state);

    memcpy(output, state, 16);
}

static const char lotus64[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/";

static int lotus64_encode(const unsigned char *in, int inlen, char *out, int outmax) {
    int i, j = 0;
    for (i = 0; i + 2 < inlen; i += 3) {
        if (j + 4 > outmax) break;
        out[j++] = lotus64[in[i] >> 2];
        out[j++] = lotus64[((in[i] & 3) << 4) | (in[i+1] >> 4)];
        out[j++] = lotus64[((in[i+1] & 0xf) << 2) | (in[i+2] >> 6)];
        out[j++] = lotus64[in[i+2] & 0x3f];
    }
    if (i < inlen && j + 2 <= outmax) {
        out[j++] = lotus64[in[i] >> 2];
        if (i + 1 < inlen) {
            out[j++] = lotus64[((in[i] & 3) << 4) | (in[i+1] >> 4)];
            if (j < outmax) out[j++] = lotus64[(in[i+1] & 0xf) << 2];
        } else {
            out[j++] = lotus64[(in[i] & 3) << 4];
        }
    }
    if (j < outmax) out[j] = 0;
    return j;
}

/* ================================================================= */
/* Non-hex verify functions (for bcrypt, APACHE-SHA, PHPBB3, APR1)   */
/* ================================================================= */

/* APACHE-SHA: {SHA}base64(SHA1(pass)) */
static int verify_apachesha(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    unsigned char *decoded = (unsigned char *)WS->ctx2;
    const char *b64;
    int b64len, dlen;

    /* Must start with {SHA} */
    if (hashlen < 9 || memcmp(hashstr, "{SHA}", 5) != 0)
        return 0;
    b64 = hashstr + 5;
    b64len = hashlen - 5;

    /* Base64 decode */
    dlen = base64_decode(b64, b64len, decoded, WS_CTX_SIZE);
    if (dlen != 20) return 0;

    /* Compute SHA1(pass) and compare */
    SHA1(pass, passlen, sha1);
    return memcmp(sha1, decoded, 20) == 0;
}

/* BCRYPT: $2a$NN$salt(22)hash(31) — verify using crypt_blowfish */
static int verify_bcrypt(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    char *passbuf = (char *)WS->gp1;
    char *result = (char *)WS->gp2;
    extern char *crypt_rn(const char *key, const char *setting,
                          void *output, int size);
    if (hashlen < 29 || hashstr[0] != '$') return 0;
    if (passlen >= (int)WS_GP_SIZE) return 0;

    /* Cost check: bench_cost = 2^12, parsed_cost = 2^NN */
    { int cost = atoi(hashstr + 4);
      if (cost > 0 && cost < 32 &&
          verify_cost_exceeds(WS->cur_rate, 4096.0, (double)(1 << cost)))
          return 0;
    }

    /* crypt_rn needs null-terminated password */
    memcpy(passbuf, pass, passlen);
    passbuf[passlen] = 0;

    if (!crypt_rn(passbuf, hashstr, result, WS_GP_SIZE))
        return 0;
    return strncmp(result, hashstr, hashlen) == 0;
}

/* BCRYPTMD5: bcrypt(hex(rhash_msg(RHASH_MD5, pass))) */
static int verify_bcryptmd5(const char *hashstr, int hashlen, const unsigned char *pass, int passlen)
{
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    char *result = (char *)WS->gp2;
    extern char *crypt_rn(const char *key, const char *setting,
                          void *output, int size);
    if (hashlen < 29 || hashstr[0] != '$') return 0;

    { int cost = atoi(hashstr + 4);
      if (cost > 0 && cost < 32 &&
          verify_cost_exceeds(WS->cur_rate, 4096.0, (double)(1 << cost)))
          return 0;
    }

    rhash_msg(RHASH_MD5, pass, passlen, md5);
    prmd5(md5, hex, 32);
    hex[32] = 0;

    if (!crypt_rn(hex, hashstr, result, WS_GP_SIZE))
        return 0;
    return strncmp(result, hashstr, hashlen) == 0;
}

/* BCRYPTSHA1: bcrypt(hex(SHA1(pass))) */
static int verify_bcryptsha1(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    char *result = (char *)WS->gp2;
    extern char *crypt_rn(const char *key, const char *setting,
                          void *output, int size);
    if (hashlen < 29 || hashstr[0] != '$') return 0;

    { int cost = atoi(hashstr + 4);
      if (cost > 0 && cost < 32 &&
          verify_cost_exceeds(WS->cur_rate, 4096.0, (double)(1 << cost)))
          return 0;
    }

    SHA1(pass, passlen, sha1);
    prmd5(sha1, hex, 40);
    hex[40] = 0;

    if (!crypt_rn(hex, hashstr, result, WS_GP_SIZE))
        return 0;
    return strncmp(result, hashstr, hashlen) == 0;
}

/* bcrypt(sha256($pass)) — mode 30600: SHA256 → hex → bcrypt */
static int verify_bcryptsha256(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    char *result = (char *)WS->gp2;
    extern char *crypt_rn(const char *key, const char *setting,
                          void *output, int size);
    if (hashlen < 29 || hashstr[0] != '$') return 0;

    { int cost = atoi(hashstr + 4);
      if (cost > 0 && cost < 32 &&
          verify_cost_exceeds(WS->cur_rate, 4096.0, (double)(1 << cost)))
          return 0;
    }

    SHA256(pass, passlen, sha);
    prmd5(sha, hex, 64);
    hex[64] = 0;

    if (!crypt_rn(hex, hashstr, result, WS_GP_SIZE))
        return 0;
    return strncmp(result, hashstr, hashlen) == 0;
}

/* bcrypt(HMAC-SHA256($pass)) — mode 30601
 * Format: $bcrypt-sha256$v=2,t=2b,r=NN$SALT22$HASH31
 * Algorithm: HMAC-SHA256(key=salt_b64_string, data=pass) → standard base64 → bcrypt */
static int verify_bcrypthmacsha256(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *hmac_out = (unsigned char *)WS->ctx1;
    char *setting = (char *)WS->gp1;
    char *result = (char *)WS->gp2;
    char *b64 = (char *)WS->gp3;
    unsigned int hmac_len = 32;
    extern char *crypt_rn(const char *key, const char *setting,
                          void *output, int size);

    /* $bcrypt-sha256$v=2,t=2b,r=NN$SALT22$HASH31 */
    if (hashlen < 40 || memcmp(hashstr, "$bcrypt-sha256$v=2,t=2b,r=", 26) != 0)
        return 0;

    /* Parse rounds */
    const char *rp = hashstr + 26;
    const char *d1 = strchr(rp, '$');
    if (!d1 || d1 - rp > 2) return 0;
    int rounds = atoi(rp);
    if (rounds < 1 || rounds > 31) return 0;

    { int cost = rounds;
      if (cost > 0 && cost < 32 &&
          verify_cost_exceeds(WS->cur_rate, 4096.0, (double)(1 << cost)))
          return 0;
    }

    /* Salt is 22 chars of bcrypt base64 */
    const char *salt22 = d1 + 1;
    if (strlen(salt22) < 22 + 1 + 31) return 0;  /* salt22$hash31 */
    if (salt22[22] != '$') return 0;

    /* HMAC-SHA256(key=salt_b64_string_22chars, data=password) */
    HMAC(EVP_sha256(), salt22, 22, pass, passlen, hmac_out, &hmac_len);

    /* Standard base64 encode (RFC 4648), keep padding */
    b64_encode(hmac_out, 32, b64);
    /* 32 bytes → 44 chars including trailing '=' */

    /* Build bcrypt setting: $2b$NN$salt22 */
    sprintf(setting, "$2b$%02d$%.22s", rounds, salt22);

    if (!crypt_rn(b64, setting, result, WS_GP_SIZE))
        return 0;

    /* Compare: rebuild full format string and compare
     * result has $2b$NN$salt22+hash31
     * We need to compare the hash31 part */
    const char *expected_hash = salt22 + 23;  /* skip salt22$ */
    int setting_len = strlen(setting);  /* $2b$NN$salt22 */
    const char *computed_hash = result + setting_len;
    return strncmp(computed_hash, expected_hash, 31) == 0;
}

/* Django SHA-1 (mode 124): sha1$SALT$HEXHASH40 → SHA1(salt + pass)
 * Also handles plain HEXHASH40:SALT format for self-test compatibility */
static int verify_django_sha1(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *computed = (unsigned char *)WS->ctx1;
    unsigned char *expected = (unsigned char *)WS->ctx2;
    const char *salt;
    int saltlen;

    if (hashlen >= 50 && memcmp(hashstr, "sha1$", 5) == 0) {
        /* Django format: sha1$SALT$HEXHASH40 */
        salt = hashstr + 5;
        const char *d1 = memchr(salt, '$', hashlen - 5);
        if (!d1) return 0;
        saltlen = d1 - salt;
        if (saltlen < 1 || saltlen > 32) return 0;
        const char *hashpart = d1 + 1;
        int hashpartlen = hashlen - (hashpart - hashstr);
        if (hashpartlen != 40) return 0;
        if (hex2bin(hashpart, 40, expected) != 20) return 0;
    } else if (hashlen >= 41 && hashstr[40] == ':') {
        /* Plain format: HEXHASH40:SALT */
        if (hex2bin(hashstr, 40, expected) != 20) return 0;
        salt = hashstr + 41;
        saltlen = hashlen - 41;
        if (saltlen < 1 || saltlen > 255) return 0;
    } else {
        return 0;
    }

    /* SHA1(salt + pass) */
    rhash ctx = rhash_init(RHASH_SHA1);
    rhash_update(ctx, salt, saltlen);
    rhash_update(ctx, pass, passlen);
    rhash_final(ctx, computed);
    rhash_free(ctx);

    return memcmp(computed, expected, 20) == 0;
}

/* PHPBB3 ($H$): phpass-style iterated MD5 */
static int verify_phpbb3(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    static const char itoa64[] =
        "./0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    rhash ctx;
    int count, i;
    const char *salt;
    char *p;

    /* Format: $H$NSALT(8)HASH(22) or $P$NSALT(8)HASH(22) = 34 chars total */
    if (hashlen < 34 || (memcmp(hashstr, "$H$", 3) != 0 && memcmp(hashstr, "$P$", 3) != 0))
        return 0;

    /* Count = 2^(index of hashstr[3] in itoa64) */
    p = strchr(itoa64, hashstr[3]);
    if (!p) return 0;
    count = 1 << (int)(p - itoa64);
    if (verify_cost_exceeds(WS->cur_rate, 2048.0, (double)count)) return 0;
    salt = hashstr + 4;  /* 8-char salt */

    /* Initial: rhash_msg(RHASH_MD5, salt + pass) */
    ctx = rhash_init(RHASH_MD5);
    rhash_update(ctx, salt, 8);
    rhash_update(ctx, pass, passlen);
    rhash_final(ctx, md5); rhash_free(ctx);

    /* Iterate: rhash_msg(RHASH_MD5, md5_binary + pass) */
    for (i = 0; i < count; i++) {
        ctx = rhash_init(RHASH_MD5);
        rhash_update(ctx, md5, 16);
        rhash_update(ctx, pass, passlen);
        rhash_final(ctx, md5); rhash_free(ctx);
    }

    /* Encode with phpass base64 and compare */
    {
        unsigned char *h = md5;
        char *encoded = (char *)WS->gp1;
        int eidx = 0, bidx = 0, bits;

        while (bidx < 16) {
            bits = h[bidx++];
            encoded[eidx++] = itoa64[bits & 0x3f];
            bits >>= 6;
            if (bidx < 16) bits |= h[bidx] << 2;
            encoded[eidx++] = itoa64[bits & 0x3f];
            if (bidx++ >= 16) break;
            bits >>= 6;
            if (bidx < 16) bits |= h[bidx] << 4;
            encoded[eidx++] = itoa64[bits & 0x3f];
            if (bidx++ >= 16) break;
            bits >>= 6;
            encoded[eidx++] = itoa64[bits & 0x3f];
        }
        encoded[eidx] = 0;

        /* Compare: hashstr[12..33] = encoded hash (22 chars) */
        return eidx >= 22 && memcmp(hashstr + 12, encoded, 22) == 0;
    }
}

/* APR1 ($apr1$): Apache MD5-crypt */
static int verify_apr1(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    /* APR1 format: $apr1$salt$hash */
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    unsigned char *alt = (unsigned char *)WS->ctx2;
    rhash ctx;
    const char *salt;
    int saltlen, i, plen;
    char *expected = (char *)WS->gp1;
    static const char itoa64[] =
        "./0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    if (hashlen < 10 || memcmp(hashstr, "$apr1$", 6) != 0)
        return 0;

    /* Extract salt (between 2nd and 3rd $) */
    salt = hashstr + 6;
    for (saltlen = 0; saltlen < 8 && salt[saltlen] && salt[saltlen] != '$'; saltlen++)
        ;
    if (salt[saltlen] != '$') return 0;

    plen = passlen;

    /* Step 1: alt = md5(pass + salt + pass) — compute first to avoid
     * aliasing with ctx (ws_rhash_init reuses single MD5 context) */
    ctx = rhash_init(RHASH_MD5);
    rhash_update(ctx, pass, plen);
    rhash_update(ctx, salt, saltlen);
    rhash_update(ctx, pass, plen);
    rhash_final(ctx, alt); rhash_free(ctx);

    /* Step 2: md5(pass + "$apr1$" + salt + alt_bytes...) */
    ctx = rhash_init(RHASH_MD5);
    rhash_update(ctx, pass, plen);
    rhash_update(ctx, "$apr1$", 6);
    rhash_update(ctx, salt, saltlen);

    /* Add alternate to main, plen bytes */
    for (i = plen; i > 0; i -= 16)
        rhash_update(ctx, alt, (i > 16) ? 16 : i);

    /* Add pass length bits */
    for (i = plen; i > 0; i >>= 1) {
        if (i & 1)
            rhash_update(ctx, "", 1);  /* NUL byte */
        else
            rhash_update(ctx, pass, 1);
    }
    rhash_final(ctx, md5); rhash_free(ctx);

    /* 1000 iterations */
    for (i = 0; i < 1000; i++) {
        ctx = rhash_init(RHASH_MD5);
        if (i & 1)
            rhash_update(ctx, pass, plen);
        else
            rhash_update(ctx, md5, 16);
        if (i % 3)
            rhash_update(ctx, salt, saltlen);
        if (i % 7)
            rhash_update(ctx, pass, plen);
        if (i & 1)
            rhash_update(ctx, md5, 16);
        else
            rhash_update(ctx, pass, plen);
        rhash_final(ctx, md5); rhash_free(ctx);
    }

    /* Encode result in md5crypt base64 format */
    {
        /* md5crypt groups: (0,6,12) (1,7,13) (2,8,14) (3,9,15) (4,10,5) 11 */
        static const unsigned char grp[][3] = {
            {0,6,12}, {1,7,13}, {2,8,14}, {3,9,15}, {4,10,5}
        };
        char *enc = (char *)WS->gp2;
        int eidx = 0, g;
        unsigned int v;

        for (g = 0; g < 5; g++) {
            v = ((unsigned int)md5[grp[g][0]] << 16)
              | ((unsigned int)md5[grp[g][1]] << 8)
              | md5[grp[g][2]];
            enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
            enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
            enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
            enc[eidx++] = itoa64[v & 0x3f];
        }
        /* Last byte: md5[11] */
        v = md5[11];
        enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
        enc[eidx++] = itoa64[v & 0x3f];
        enc[eidx] = 0;

        /* Build expected: $apr1$salt$encoded */
        snprintf(expected, WS_GP_SIZE, "$apr1$%.*s$%s",
                 saltlen, salt, enc);
        return strncmp(expected, hashstr, hashlen) == 0;
    }
}

/* POSTGRESQL (e855): md5(pass + username) → "md5" + 32hex ":" username
 * Also accepts bare 32hex ":" username (without "md5" prefix) */
static int verify_postgresql(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    char *hex = (char *)WS->gp1;
    const char *colon, *hexpart;
    int hpart, hexoff;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;

    /* Accept "md5" + 32hex (hpart=35) or bare 32hex (hpart=32) */
    if (hpart == 35 && memcmp(hashstr, "md5", 3) == 0) {
        hexoff = 3;
    } else if (hpart == 32) {
        hexoff = 0;
    } else {
        return 0;
    }
    hexpart = hashstr + hexoff;

    /* md5(pass + username) */
    { const char *username = colon + 1;
      int ulen = hashlen - hpart - 1;
      unsigned char *buf = (unsigned char *)WS->gp2;
      if (passlen + ulen > (int)WS_GP_SIZE) return 0;
      memcpy(buf, pass, passlen);
      memcpy(buf + passlen, username, ulen);
      rhash_msg(RHASH_MD5, buf, passlen + ulen, md5);
    }
    prmd5(md5, hex, 32);
    hex[32] = 0;
    return memcmp(hex, hexpart, 32) == 0;
}

/* PEOPLESOFT (e858): base64(SHA1(UTF16LE(pass))) — 28 chars */
static int verify_peoplesoft(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *utf16 = (unsigned char *)WS->u16a;
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    char *b64 = (char *)WS->gp1;
    int u16len;

    if (hashlen != 28) return 0;
    u16len = utf8_to_utf16le(pass, passlen, utf16, WS_U16_SIZE);
    if (u16len <= 0) return 0;
    SHA1(utf16, u16len, sha1);
    b64_encode(sha1, 20, b64);
    return memcmp(b64, hashstr, 28) == 0;
}

/* HMAILSERVER (e860): SHA256(salt + pass) — 6hex_salt + 64hex_hash (70 chars) */
static int verify_hmailserver(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha256 = (unsigned char *)WS->ctx1;
    char *computed = (char *)WS->gp1;

    if (hashlen != 70) return 0;
    /* salt is first 6 chars (hex string used as-is) */
    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (6 + passlen > WS_GP_SIZE) return 0;
      memcpy(buf, hashstr, 6);
      memcpy(buf + 6, pass, passlen);
      SHA256(buf, 6 + passlen, sha256);
    }
    memcpy(computed, hashstr, 6);
    prmd5(sha256, computed + 6, 64);
    computed[70] = 0;
    return strncasecmp(computed, hashstr, 70) == 0;
}

/* MEDIAWIKI (e863): md5(salt + "-" + md5(pass)) — "$B$" salt "$" 32hex */
static int verify_mediawiki(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *md5_inner = (unsigned char *)WS->ctx1;
    unsigned char *md5_outer = (unsigned char *)WS->ctx2;
    char *hex_inner = (char *)WS->gp1;
    char *computed = (char *)WS->gp2;
    const char *salt, *hash_part;
    int saltlen;

    if (hashlen < 10 || memcmp(hashstr, "$B$", 3) != 0) return 0;
    salt = hashstr + 3;
    hash_part = memchr(salt, '$', hashlen - 3);
    if (!hash_part) return 0;
    saltlen = hash_part - salt;
    hash_part++;
    if (hashstr + hashlen - hash_part != 32) return 0;

    rhash_msg(RHASH_MD5, pass, passlen, md5_inner);
    prmd5(md5_inner, hex_inner, 32);
    hex_inner[32] = 0;

    { unsigned char *buf = (unsigned char *)WS->gp3;
      if (saltlen + 1 + 32 > WS_GP_SIZE) return 0;
      memcpy(buf, salt, saltlen);
      buf[saltlen] = '-';
      memcpy(buf + saltlen + 1, hex_inner, 32);
      rhash_msg(RHASH_MD5, buf, saltlen + 1 + 32, md5_outer);
    }
    snprintf(computed, WS_GP_SIZE, "$B$%.*s$", saltlen, salt);
    prmd5(md5_outer, computed + 4 + saltlen, 32);
    computed[4 + saltlen + 32] = 0;
    return hashlen == (int)strlen(computed) && memcmp(computed, hashstr, hashlen) == 0;
}

/* DAHUA (e864): md5(salt + UC(md5(pepper + pass)))
 * Format: 32hex_hash:salt:pepper:password */
static int verify_dahua(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *md5_inner = (unsigned char *)WS->ctx1;
    unsigned char *md5_outer = (unsigned char *)WS->ctx2;
    char *uchex = (char *)WS->gp1;
    const char *c1, *c2, *salt, *pepper;
    int saltlen, peplen;

    /* Parse hash:salt:pepper */
    c1 = memchr(hashstr, ':', hashlen);
    if (!c1) return 0;
    if (c1 - hashstr != 32) return 0;
    c2 = memchr(c1 + 1, ':', hashlen - (c1 + 1 - hashstr));
    if (!c2) return 0;
    salt = c1 + 1;
    saltlen = c2 - salt;
    pepper = c2 + 1;
    peplen = hashlen - (pepper - hashstr);

    /* md5(pepper + pass) */
    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (peplen + passlen > WS_GP_SIZE) return 0;
      memcpy(buf, pepper, peplen);
      memcpy(buf + peplen, pass, passlen);
      rhash_msg(RHASH_MD5, buf, peplen + passlen, md5_inner);
    }
    prmd5UC(md5_inner, uchex, 32);
    uchex[32] = 0;

    /* md5(salt + UC_hex) */
    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (saltlen + 32 > WS_GP_SIZE) return 0;
      memcpy(buf, salt, saltlen);
      memcpy(buf + saltlen, uchex, 32);
      rhash_msg(RHASH_MD5, buf, saltlen + 32, md5_outer);
    }
    { char out[33];
      prmd5(md5_outer, out, 32);
      return strncasecmp(out, hashstr, 32) == 0;
    }
}

/* NETSCALER (e878): SHA1(salt_hex_str + pass + \0) — "1" + 8hex_salt + 40hex */
static int verify_netscaler(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    char *computed = (char *)WS->gp1;

    if (hashlen != 49 || hashstr[0] != '1') return 0;
    /* SHA1(8-char hex salt string + password + NUL byte) */
    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (8 + passlen + 1 > WS_GP_SIZE) return 0;
      memcpy(buf, hashstr + 1, 8); /* salt as hex string */
      memcpy(buf + 8, pass, passlen);
      buf[8 + passlen] = 0;
      SHA1(buf, 8 + passlen + 1, sha1);
    }
    computed[0] = '1';
    memcpy(computed + 1, hashstr + 1, 8);
    prmd5(sha1, computed + 9, 40);
    computed[49] = 0;
    return strncasecmp(computed, hashstr, 49) == 0;
}

/* NETSCALER-SHA512 (e893): SHA512(8-char salt + pass + NUL) — prefix "2" + 8salt + 128hex */
static int verify_netscaler512(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha_out = (unsigned char *)WS->ctx1;
    char *computed = (char *)WS->gp1;
    char *buf = (char *)WS->gp2;

    if (hashlen != 137 || hashstr[0] != '2') return 0;
    if (8 + passlen + 1 > (int)WS_GP_SIZE) return 0;
    memcpy(buf, hashstr + 1, 8);
    memcpy(buf + 8, pass, passlen);
    buf[8 + passlen] = 0;
    rhash_msg(RHASH_SHA512, (unsigned char *)buf, 8 + passlen + 1, sha_out);
    computed[0] = '2';
    memcpy(computed + 1, hashstr + 1, 8);
    prmd5(sha_out, computed + 9, 128);
    computed[137] = 0;
    return strncasecmp(computed, hashstr, 137) == 0;
}

/* NETSCALER-PBKDF2 (e895): Citrix NetScaler PBKDF2-HMAC-SHA256
 * Format: "5" + 64-hex-salt + 64-hex-hash (129 chars total), 2500 iterations */
static int verify_netscaler_pbkdf2(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *salt_bin = (unsigned char *)WS->gp1;
    unsigned char *derived = (unsigned char *)WS->ctx1;
    unsigned char *expected = (unsigned char *)WS->ctx2;
    int salt_len, hash_len;

    if (hashlen != 129 || hashstr[0] != '5') return 0;
    salt_len = hex2bin(hashstr + 1, 64, salt_bin);
    if (salt_len != 32) return 0;
    hash_len = hex2bin(hashstr + 65, 64, expected);
    if (hash_len != 32) return 0;
    PKCS5_PBKDF2_HMAC((const char *)pass, passlen,
        salt_bin, 32, 2500, EVP_sha256(), 32, derived);
    return memcmp(derived, expected, 32) == 0;
}

/* ORACLE7 (e896): Oracle H: Type (Oracle 7+) — DES-CBC based
 * Format: 16-hex-UC-hash:username (1-30 char salt)
 * Algorithm: uppercase salt+pass, pad to mult-of-8 with nulls,
 * zero-extend each byte to 16-bit BE, DES-CBC(key=0123456789ABCDEF, IV=0),
 * last 8-byte block → new key, DES-CBC again with new key, IV=0,
 * last 8-byte block = hash */
static int verify_oracle7(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *buf = (unsigned char *)WS->gp1;  /* wide data: up to (30+30)*2 = 120 bytes */
    unsigned char *expected = (unsigned char *)WS->ctx1;
    DES_key_schedule *ks = (DES_key_schedule *)WS->ctx2;
    unsigned char *iv = (unsigned char *)WS->gp3;       /* 8 bytes */
    unsigned char *data_blk = (unsigned char *)WS->gp4; /* 8 bytes */
    unsigned char *key = (unsigned char *)WS->gp5;      /* 8 bytes */
    const char *colon;
    int hpart, saltlen, catlen, padlen, widelen, i;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 16) return 0;
    saltlen = hashlen - hpart - 1;
    if (saltlen < 1 || saltlen > 30) return 0;
    if (passlen > 30) return 0;

    /* decode expected hash */
    if (hex2bin(hashstr, 16, expected) != 8) return 0;

    /* build uppercase salt + password, pad to mult of 4 (= 8 wide bytes per DES block) */
    catlen = saltlen + passlen;
    padlen = (catlen + 3) & ~3;
    if (padlen * 2 > (int)WS_GP_SIZE) return 0;

    /* zero-extend each byte to 16-bit big-endian into buf */
    widelen = 0;
    for (i = 0; i < saltlen; i++) {
        unsigned char c = colon[1 + i];
        if (c >= 'a' && c <= 'z') c -= 32;
        buf[widelen++] = 0;
        buf[widelen++] = c;
    }
    for (i = 0; i < passlen; i++) {
        unsigned char c = pass[i];
        if (c >= 'a' && c <= 'z') c -= 32;
        buf[widelen++] = 0;
        buf[widelen++] = c;
    }
    /* pad to mult of 4 chars (= 8 bytes = one DES block in wide form) */
    while (widelen < padlen * 2) {
        buf[widelen++] = 0;
        buf[widelen++] = 0;
    }

    /* init fixed DES key */
    key[0] = 0x01; key[1] = 0x23; key[2] = 0x45; key[3] = 0x67;
    key[4] = 0x89; key[5] = 0xAB; key[6] = 0xCD; key[7] = 0xEF;

    /* Pass 1: DES-CBC with fixed key */
    DES_set_key_unchecked((DES_cblock *)key, ks);
    memset(iv, 0, 8);
    for (i = 0; i < widelen; i += 8) {
        /* CBC: XOR plaintext block with IV, then encrypt */
        data_blk[0] = buf[i+0] ^ iv[0];
        data_blk[1] = buf[i+1] ^ iv[1];
        data_blk[2] = buf[i+2] ^ iv[2];
        data_blk[3] = buf[i+3] ^ iv[3];
        data_blk[4] = buf[i+4] ^ iv[4];
        data_blk[5] = buf[i+5] ^ iv[5];
        data_blk[6] = buf[i+6] ^ iv[6];
        data_blk[7] = buf[i+7] ^ iv[7];
        DES_ecb_encrypt((const_DES_cblock *)data_blk, (DES_cblock *)iv, ks, DES_ENCRYPT);
    }

    /* Pass 2: DES-CBC with key = last block from pass 1 */
    DES_set_key_unchecked((DES_cblock *)iv, ks);
    memset(iv, 0, 8);
    for (i = 0; i < widelen; i += 8) {
        data_blk[0] = buf[i+0] ^ iv[0];
        data_blk[1] = buf[i+1] ^ iv[1];
        data_blk[2] = buf[i+2] ^ iv[2];
        data_blk[3] = buf[i+3] ^ iv[3];
        data_blk[4] = buf[i+4] ^ iv[4];
        data_blk[5] = buf[i+5] ^ iv[5];
        data_blk[6] = buf[i+6] ^ iv[6];
        data_blk[7] = buf[i+7] ^ iv[7];
        DES_ecb_encrypt((const_DES_cblock *)data_blk, (DES_cblock *)iv, ks, DES_ENCRYPT);
    }

    return memcmp(iv, expected, 8) == 0;
}

/* NetNTLMv1 (e897): user::domain:lm_response:ntlm_response(48hex):challenge(16hex)
 * Algorithm: NTLM=MD4(UTF16LE(pass)), pad to 21, split 3x7→DES keys,
 * DES-ECB encrypt 8-byte challenge. ESS: if lm[8:24]=0, challenge=MD5(srv+lm[0:8])[0:8] */
static int verify_netntlmv1(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *ntlm = (unsigned char *)WS->ctx1;      /* 16-byte NTLM hash */
    unsigned char *u16buf = (unsigned char *)WS->u16a;
    unsigned char *expected = (unsigned char *)WS->ctx2;   /* 24-byte expected response */
    unsigned char *computed = (unsigned char *)WS->ctx3;   /* 24-byte computed response */
    unsigned char *challenge = (unsigned char *)WS->gp1;   /* 8-byte effective challenge */
    unsigned char *lm_bin = (unsigned char *)WS->gp2;      /* LM response binary */
    unsigned char *padded = (unsigned char *)WS->gp3;      /* 21 bytes */
    DES_key_schedule *ks = (DES_key_schedule *)WS->ctx4;
    unsigned char *combo = (unsigned char *)WS->gp4;       /* 16 bytes for ESS */
    const char *f[6];   /* field pointers — small, OK on stack */
    int flen[6];
    int i, nf = 0;
    const char *end = hashstr + hashlen;

    /* parse 6 colon-separated fields */
    f[0] = hashstr;
    for (i = 0; i < hashlen && nf < 5; i++) {
        if (hashstr[i] == ':') {
            flen[nf] = &hashstr[i] - f[nf];
            nf++;
            f[nf] = &hashstr[i + 1];
        }
    }
    if (nf != 5) return 0;
    flen[5] = end - f[5];

    /* field 1 (index 1) must be empty */
    if (flen[1] != 0) return 0;
    /* field 4 (ntlm_response) must be 48 hex */
    if (flen[4] != 48) return 0;
    /* field 5 (challenge) must be 16 hex */
    if (flen[5] != 16) return 0;

    /* decode ntlm_response (24 bytes) and challenge (8 bytes) */
    if (hex2bin(f[4], 48, expected) != 24) return 0;
    if (hex2bin(f[5], 16, challenge) != 8) return 0;

    /* compute NTLM hash: MD4(UTF16LE(pass)) — blind zero-extension */
    for (i = 0; i < passlen; i++) { u16buf[i*2] = pass[i]; u16buf[i*2+1] = 0; }
    rhash_msg(RHASH_MD4, u16buf, passlen * 2, ntlm);

    /* check for ESS: LM response is 48 hex with bytes 8-23 all zero */
    if (flen[3] == 48) {
        if (hex2bin(f[3], 48, lm_bin) == 24) {
            int ess = 1;
            for (i = 8; i < 24; i++) { if (lm_bin[i] != 0) { ess = 0; break; } }
            if (ess) {
                /* ESS: effective challenge = MD5(srvchall + clichall)[0:8] */
                unsigned char *md5out = (unsigned char *)WS->gp5;
                memcpy(combo, challenge, 8);
                memcpy(combo + 8, lm_bin, 8);
                rhash_msg(RHASH_MD5, combo, 16, md5out);
                memcpy(challenge, md5out, 8);
            }
        }
    }

    /* pad NTLM hash to 21 bytes, split into 3 DES keys, encrypt challenge */
    memcpy(padded, ntlm, 16);
    memset(padded + 16, 0, 5);
    lm_des_key(padded, ks);
    DES_ecb_encrypt((const_DES_cblock *)challenge, (DES_cblock *)(computed), ks, DES_ENCRYPT);
    lm_des_key(padded + 7, ks);
    DES_ecb_encrypt((const_DES_cblock *)challenge, (DES_cblock *)(computed + 8), ks, DES_ENCRYPT);
    lm_des_key(padded + 14, ks);
    DES_ecb_encrypt((const_DES_cblock *)challenge, (DES_cblock *)(computed + 16), ks, DES_ENCRYPT);

    return memcmp(computed, expected, 24) == 0;
}

/* NetNTLMv2 (e898): user::domain:srvchall(16hex):response(32hex):client_blob(hex)
 * Algorithm: NTLMv2_hash = HMAC-MD5(NTLM_hash, UC(user_UTF16LE) + domain_UTF16LE)
 *            response = HMAC-MD5(NTLMv2_hash, srvchall_bin + client_blob_bin)[0:16] */
static int verify_netntlmv2(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *ntlm = (unsigned char *)WS->ctx1;
    unsigned char *ntlmv2 = (unsigned char *)WS->ctx2;
    unsigned char *expected = (unsigned char *)WS->ctx3;
    unsigned char *computed = (unsigned char *)WS->ctx4;
    unsigned char *u16buf = (unsigned char *)WS->u16a;
    unsigned char *blob = (unsigned char *)WS->gp1;
    unsigned char *srvchall = (unsigned char *)WS->gp2;
    const char *f[6];
    int flen[6];
    int i, nf = 0, u16len, bloblen;

    /* parse 6 colon-separated fields */
    f[0] = hashstr;
    for (i = 0; i < hashlen && nf < 5; i++) {
        if (hashstr[i] == ':') {
            flen[nf] = &hashstr[i] - f[nf];
            nf++;
            f[nf] = &hashstr[i + 1];
        }
    }
    if (nf != 5) return 0;
    flen[5] = (hashstr + hashlen) - f[5];

    /* field 1 must be empty */
    if (flen[1] != 0) return 0;
    /* field 3 (srvchall) must be 16 hex */
    if (flen[3] != 16) return 0;
    /* field 4 (response hash) must be 32 hex */
    if (flen[4] != 32) return 0;
    /* field 5 (client_blob) must be even-length hex, >= 2 */
    if (flen[5] < 2 || (flen[5] & 1)) return 0;

    /* decode fields */
    if (hex2bin(f[3], 16, srvchall) != 8) return 0;
    if (hex2bin(f[4], 32, expected) != 16) return 0;
    bloblen = hex2bin(f[5], flen[5], blob);
    if (bloblen <= 0) return 0;

    /* NTLM hash: MD4(UTF16LE(pass)) */
    for (i = 0; i < passlen; i++) { u16buf[i*2] = pass[i]; u16buf[i*2+1] = 0; }
    rhash_msg(RHASH_MD4, u16buf, passlen * 2, ntlm);

    /* NTLMv2 hash: HMAC-MD5(ntlm, UC(user_UTF16LE) + domain_UTF16LE) */
    u16len = 0;
    for (i = 0; i < flen[0]; i++) {
        unsigned char c = f[0][i];
        if (c >= 'a' && c <= 'z') c -= 32;
        u16buf[u16len++] = c;
        u16buf[u16len++] = 0;
    }
    for (i = 0; i < flen[2]; i++) {
        u16buf[u16len++] = f[2][i];
        u16buf[u16len++] = 0;
    }
    { unsigned int hmlen = 16;
      HMAC(EVP_md5(), ntlm, 16, u16buf, u16len, ntlmv2, &hmlen);
    }

    /* response: HMAC-MD5(ntlmv2, srvchall + client_blob) */
    /* build srvchall + blob in u16buf (reuse, has enough space) */
    memcpy(u16buf, srvchall, 8);
    memcpy(u16buf + 8, blob, bloblen);
    { unsigned int hmlen = 16;
      HMAC(EVP_md5(), ntlmv2, 16, u16buf, 8 + bloblen, computed, &hmlen);
    }

    return memcmp(computed, expected, 16) == 0;
}

/* LASTPASS (e899): LastPass + LastPass sniffed (hashcat mode 6800)
 * Format: hash(32hex):iterations:email:iv(32hex)
 * Algorithm: key = PBKDF2-HMAC-SHA256(pass, email, iterations, 32)
 *   Offline:  AES-256-ECB-encrypt("lastpass rocks\x02\x02", key) == hash
 *   Sniffed:  AES-256-ECB-decrypt(hash, key) XOR IV, truncated to len(email) == email */
static int verify_lastpass(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *derived = (unsigned char *)WS->ctx1;   /* 32-byte PBKDF2 output */
    unsigned char *expected = (unsigned char *)WS->ctx2;  /* 16-byte hash */
    unsigned char *computed = (unsigned char *)WS->ctx3;  /* 16-byte AES output */
    unsigned char *iv_bin = (unsigned char *)WS->gp1;     /* 16-byte IV */
    AES_KEY *aeskey = (AES_KEY *)WS->ctx4;
    const char *f[4];
    int flen[4];
    int i, nf = 0, iterations, emaillen;

    /* parse 3 or 4 colon-separated fields:
     * Old format (offline only): hash:iterations:email
     * New format (offline + sniffed): hash:iterations:email:iv */
    f[0] = hashstr;
    for (i = 0; i < hashlen && nf < 3; i++) {
        if (hashstr[i] == ':') {
            flen[nf] = &hashstr[i] - f[nf];
            nf++;
            f[nf] = &hashstr[i + 1];
        }
    }
    if (nf < 2 || nf > 3) return 0;
    flen[nf] = (hashstr + hashlen) - f[nf];

    /* field 0: hash must be 32 hex (16 bytes) */
    if (flen[0] != 32) return 0;
    /* field 1: iterations (1-6 digits) */
    if (flen[1] < 1 || flen[1] > 6) return 0;
    iterations = 0;
    for (i = 0; i < flen[1]; i++) {
        if (f[1][i] < '0' || f[1][i] > '9') return 0;
        iterations = iterations * 10 + (f[1][i] - '0');
    }
    if (iterations < 1) return 0;
    if (verify_cost_exceeds(WS->cur_rate, 100100.0, (double)iterations)) return 0;
    /* field 2: email (0-32 chars) */
    emaillen = flen[2];
    if (emaillen > 32) return 0;
    /* field 3 (optional): IV must be 32 hex (16 bytes) */
    if (nf == 3 && flen[3] != 32) return 0;

    /* decode hash */
    if (hex2bin(f[0], 32, expected) != 16) return 0;
    /* decode IV if present */
    if (nf == 3) {
        if (hex2bin(f[3], 32, iv_bin) != 16) return 0;
    }

    /* derive key: PBKDF2-HMAC-SHA256(pass, email, iterations, 32) */
    PKCS5_PBKDF2_HMAC((const char *)pass, passlen,
        (const unsigned char *)f[2], emaillen, iterations,
        EVP_sha256(), 32, derived);

    /* Try offline mode: AES-256-ECB-encrypt("lastpass rocks\x02\x02") */
    {
        static const unsigned char lastpass_magic[16] = {
            'l','a','s','t','p','a','s','s',
            ' ','r','o','c','k','s',0x02,0x02
        };
        AES_set_encrypt_key(derived, 256, aeskey);
        AES_ecb_encrypt(lastpass_magic, computed, aeskey, AES_ENCRYPT);
        if (memcmp(computed, expected, 16) == 0) return 1;
    }

    /* Try sniffed mode: AES-256-ECB-decrypt(hash), XOR IV, compare email */
    if (nf == 3 && emaillen > 0) {
        int cmplen = emaillen < 16 ? emaillen : 16;
        unsigned char *plain = (unsigned char *)WS->gp2;
        AES_set_decrypt_key(derived, 256, aeskey);
        AES_ecb_encrypt(expected, computed, aeskey, AES_DECRYPT);
        for (i = 0; i < 16; i++)
            plain[i] = computed[i] ^ iv_bin[i];
        if (memcmp(plain, f[2], cmplen) == 0) return 1;
    }

    return 0;
}

/* FORTIGATE (e900): FortiGate (FortiOS) — hashcat mode 7000
 * Format: "AK1" + 44 chars base64 (47 chars total)
 * Base64 decodes to 32 bytes: 12-byte salt + 20-byte SHA1(salt + pass + magic)
 * Magic = 24-byte constant from FortiGate firmware */
static int verify_fortigate(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    static const unsigned char fortigate_magic[24] = {
        0xa3,0x88,0xba,0x2e,0x42,0x4c,0xb0,0x4a,
        0x53,0x79,0x30,0xc1,0x31,0x07,0xcc,0x3f,
        0xa1,0x32,0x90,0x29,0xa9,0x81,0x5b,0x70
    };
    unsigned char *decoded = (unsigned char *)WS->gp1;
    unsigned char *computed = (unsigned char *)WS->ctx1;
    SHA_CTX *sha_ctx = (SHA_CTX *)WS->ctx2;

    if (hashlen != 47) return 0;
    if (memcmp(hashstr, "AK1", 3) != 0) return 0;

    int dlen = base64_decode(hashstr + 3, 44, decoded, 64);
    if (dlen != 32) return 0;

    /* SHA1(salt[12] + pass + magic[24]) */
    SHA1_Init(sha_ctx);
    SHA1_Update(sha_ctx, decoded, 12);
    SHA1_Update(sha_ctx, pass, passlen);
    SHA1_Update(sha_ctx, fortigate_magic, 24);
    SHA1_Final(computed, sha_ctx);

    return memcmp(computed, decoded + 12, 20) == 0;
}

/* SHA1SHA1SALTPASSSALT (e894): sha1(sha1(salt+pass+salt)) — 40hex:salt */
static int verify_sha1sha1saltpasssalt(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    char *hex1 = (char *)WS->gp1;
    char *buf = (char *)WS->gp2;
    const char *colon;
    int hpart, saltlen;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 40) return 0;
    saltlen = hashlen - hpart - 1;
    if (saltlen <= 0) return 0;
    if (saltlen + passlen + saltlen > (int)WS_GP_SIZE) return 0;

    /* inner: sha1(salt + pass + salt) */
    memcpy(buf, colon + 1, saltlen);
    memcpy(buf + saltlen, pass, passlen);
    memcpy(buf + saltlen + passlen, colon + 1, saltlen);
    SHA1((unsigned char *)buf, saltlen + passlen + saltlen, sha1);
    /* outer: sha1(hex(inner)) */
    prmd5(sha1, hex1, 40);
    SHA1((unsigned char *)hex1, 40, sha1);
    prmd5(sha1, hex1, 40);
    hex1[40] = 0;
    return strncasecmp(hex1, hashstr, 40) == 0;
}

/* WBB3 (e880): SHA1(salt + SHA1(salt + SHA1(pass))) — 40hex ":" 40hex_salt */
static int verify_wbb3(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    char *hex1 = (char *)WS->gp1;
    char *hex2 = (char *)WS->gp2;
    char *hex3 = (char *)WS->gp3;
    const char *colon;
    int hpart;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 40) return 0;
    if (hashlen - hpart - 1 != 40) return 0;

    /* h1 = sha1(pass) → hex */
    SHA1(pass, passlen, sha1);
    prmd5(sha1, hex1, 40);
    /* h2 = sha1(salt_hex + h1_hex) */
    { unsigned char buf[80];
      memcpy(buf, colon + 1, 40);
      memcpy(buf + 40, hex1, 40);
      SHA1(buf, 80, sha1);
    }
    prmd5(sha1, hex2, 40);
    /* h3 = sha1(salt_hex + h2_hex) */
    { unsigned char buf[80];
      memcpy(buf, colon + 1, 40);
      memcpy(buf + 40, hex2, 40);
      SHA1(buf, 80, sha1);
    }
    prmd5(sha1, hex3, 40);
    return strncasecmp(hex3, hashstr, 40) == 0;
}

/* MSSQL2000 (e850): 0x0100 + salt(8hex) + SHA1_cs(40hex) + SHA1_uc(40hex)
 * SHA1_cs = SHA1(UTF16LE(pass) + salt), SHA1_uc = SHA1(UTF16LE(UC(pass)) + salt)
 * mdxfind: CS at offset 14, UC at 54. hashcat may zero out CS. Try both. */
static int verify_mssql2000(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *utf16 = (unsigned char *)WS->u16a;
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    char *hex = (char *)WS->gp1;
    int u16len, i;

    { int _off = 0;
    if (hashlen == 94 && strncasecmp(hashstr, "0x0100", 6) == 0)
        _off = 6;
    else if (hashlen == 92 && strncasecmp(hashstr, "0100", 4) == 0)
        _off = 4;
    else return 0;
    if (hex2bin(hashstr + _off, 8, salt_bin) != 4) return 0;

    /* Case-sensitive SHA1: SHA1(UTF16LE(pass) + salt) — check offset _off+8 */
    u16len = utf8_to_utf16le(pass, passlen, utf16, WS_U16_SIZE - 4);
    if (u16len <= 0) return 0;
    memcpy(utf16 + u16len, salt_bin, 4);
    SHA1(utf16, u16len + 4, sha1);
    prmd5(sha1, hex, 40);
    if (strncasecmp(hex, hashstr + _off + 8, 40) == 0) return 1;

    /* Uppercase SHA1: SHA1(UTF16LE(UC(pass)) + salt) — check offset 54 */
    for (i = 0; i < u16len; i += 2)
        if (utf16[i] >= 'a' && utf16[i] <= 'z' && utf16[i+1] == 0)
            utf16[i] -= 32;
    memcpy(utf16 + u16len, salt_bin, 4);
    SHA1(utf16, u16len + 4, sha1);
    prmd5(sha1, hex, 40);
    return strncasecmp(hex, hashstr + _off + 48, 40) == 0;
    }
}

/* MSSQL2005 (e851): SHA1(UTF16LE(pass) + salt) — 0x0100 + 8hex_salt + 40hex */
static int verify_mssql2005(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *utf16 = (unsigned char *)WS->u16a;
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    int u16len;

    { int _off = 0;
    if (hashlen == 54 && strncasecmp(hashstr, "0x0100", 6) == 0)
        _off = 6;
    else if (hashlen == 52 && strncasecmp(hashstr, "0100", 4) == 0)
        _off = 4;
    else return 0;
    if (hex2bin(hashstr + _off, 8, salt_bin) != 4) return 0;

    u16len = utf8_to_utf16le(pass, passlen, utf16, WS_U16_SIZE - 4);
    if (u16len <= 0) return 0;
    memcpy(utf16 + u16len, salt_bin, 4);
    SHA1(utf16, u16len + 4, sha1);

    { char hex[41];
      prmd5(sha1, hex, 40);
      return strncasecmp(hex, hashstr + _off + 8, 40) == 0;
    }
    }
}

/* MSSQL2012 (e852): SHA512(UTF16LE(pass) + salt) — 0x0200 + 8hex_salt + 128hex */
static int verify_mssql2012(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *utf16 = (unsigned char *)WS->u16a;
    unsigned char *sha512 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    int u16len;

    { int _off = 0;
    if (hashlen == 142 && strncasecmp(hashstr, "0x0200", 6) == 0)
        _off = 6;
    else if (hashlen == 140 && strncasecmp(hashstr, "0200", 4) == 0)
        _off = 4;
    else return 0;
    if (hex2bin(hashstr + _off, 8, salt_bin) != 4) return 0;

    u16len = utf8_to_utf16le(pass, passlen, utf16, WS_U16_SIZE - 4);
    if (u16len <= 0) return 0;
    memcpy(utf16 + u16len, salt_bin, 4);
    SHA512(utf16, u16len + 4, sha512);

    { char hex[129];
      prmd5(sha512, hex, 128);
      return strncasecmp(hex, hashstr + _off + 8, 128) == 0;
    }
    }
}

/* MACOSX (e853): SHA1(salt_bin + pass) — 8hex_salt + 40hex */
static int verify_macosx(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    char *hex = (char *)WS->gp1;

    if (hashlen != 48) return 0;
    if (hex2bin(hashstr, 8, salt_bin) != 4) return 0;

    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (4 + passlen > WS_GP_SIZE) return 0;
      memcpy(buf, salt_bin, 4);
      memcpy(buf + 4, pass, passlen);
      SHA1(buf, 4 + passlen, sha1);
    }
    prmd5(sha1, hex, 40);
    return strncasecmp(hex, hashstr + 8, 40) == 0;
}

/* MACOSX7 (e854): SHA512(salt_bin + pass) — 8hex_salt + 128hex */
static int verify_macosx7(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha512 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    char *hex = (char *)WS->gp1;

    if (hashlen != 136) return 0;
    if (hex2bin(hashstr, 8, salt_bin) != 4) return 0;

    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (4 + passlen > WS_GP_SIZE) return 0;
      memcpy(buf, salt_bin, 4);
      memcpy(buf + 4, pass, passlen);
      SHA512(buf, 4 + passlen, sha512);
    }
    prmd5(sha512, hex, 128);
    return strncasecmp(hex, hashstr + 8, 128) == 0;
}

/* ARUBAOS (e887, hashcat 125): SHA1(salt_bin(5) + pass) — 10hex_salt + 40hex */
static int verify_arubaos(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    char *hex = (char *)WS->gp1;

    if (hashlen != 50) return 0;
    if (hex2bin(hashstr, 10, salt_bin) != 5) return 0;

    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (5 + passlen > WS_GP_SIZE) return 0;
      memcpy(buf, salt_bin, 5);
      memcpy(buf + 5, pass, passlen);
      SHA1(buf, 5 + passlen, sha1);
    }
    prmd5(sha1, hex, 40);
    return strncasecmp(hex, hashstr + 10, 40) == 0;
}

/* DESENCRYPT (e848): DES_ECB(pass_as_key, salt_plaintext) — 16hex ":" 16hex_salt */
static int verify_desencrypt(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *expected_ct = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    unsigned char *desct = (unsigned char *)WS->ctx3;
    unsigned char *deskey = (unsigned char *)WS->ctx4;
    DES_key_schedule *desks = (DES_key_schedule *)WS->ctx5;
    const char *colon;
    int hpart;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 16) return 0;
    if (hashlen - hpart - 1 != 16) return 0;
    if (hex2bin(hashstr, 16, expected_ct) != 8) return 0;
    if (hex2bin(colon + 1, 16, salt_bin) != 8) return 0;

    memset(deskey, 0, 8);
    memcpy(deskey, pass, passlen < 8 ? passlen : 8);
    DES_set_key_unchecked((DES_cblock *)deskey, desks);
    DES_ecb_encrypt((const_DES_cblock *)salt_bin, (DES_cblock *)desct, desks, DES_ENCRYPT);
    return memcmp(desct, expected_ct, 8) == 0;
}

/* DES3ENCRYPT (e849): 3DES_ECB(pass_as_3keys, salt_plaintext) — 16hex ":" 16hex_salt */
static int verify_des3encrypt(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *expected_ct = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    unsigned char *desct = (unsigned char *)WS->ctx3;
    unsigned char *deskey1 = (unsigned char *)WS->ctx4;
    unsigned char *deskey2 = (unsigned char *)WS->ctx5;
    unsigned char *deskey3 = (unsigned char *)WS->ctx6;
    unsigned char *tmp = (unsigned char *)WS->ctx7;
    DES_key_schedule *desks1 = (DES_key_schedule *)WS->ctx8;
    DES_key_schedule *desks2 = (DES_key_schedule *)WS->ctx9;
    DES_key_schedule *desks3 = (DES_key_schedule *)WS->ctx10;
    const char *colon;
    int hpart;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 16) return 0;
    if (hashlen - hpart - 1 != 16) return 0;
    if (hex2bin(hashstr, 16, expected_ct) != 8) return 0;
    if (hex2bin(colon + 1, 16, salt_bin) != 8) return 0;

    memset(deskey1, 0, 8); memset(deskey2, 0, 8); memset(deskey3, 0, 8);
    if (passlen >= 8) memcpy(deskey1, pass, 8); else memcpy(deskey1, pass, passlen);
    if (passlen > 8) { if (passlen >= 16) memcpy(deskey2, pass+8, 8); else memcpy(deskey2, pass+8, passlen-8); }
    if (passlen > 16) { if (passlen >= 24) memcpy(deskey3, pass+16, 8); else memcpy(deskey3, pass+16, passlen-16); }
    DES_set_key_unchecked((DES_cblock *)deskey1, desks1);
    DES_set_key_unchecked((DES_cblock *)deskey2, desks2);
    DES_set_key_unchecked((DES_cblock *)deskey3, desks3);
    /* 3DES EDE: encrypt with k1, decrypt with k2, encrypt with k3 */
    DES_ecb_encrypt((const_DES_cblock *)salt_bin, (DES_cblock *)tmp, desks1, DES_ENCRYPT);
    DES_ecb_encrypt((const_DES_cblock *)tmp, (DES_cblock *)tmp, desks2, DES_DECRYPT);
    DES_ecb_encrypt((const_DES_cblock *)tmp, (DES_cblock *)desct, desks3, DES_ENCRYPT);
    return memcmp(desct, expected_ct, 8) == 0;
}

/* RACF (e881): DES_ECB(EBCDIC_UC_username, EBCDIC_pass_key) — 16hex ":" username */
/* RVARY (e1012): DES-ECB of the EBCDIC password, keyed by the RACF key
 * schedule from that same password. Unlike RACF the plaintext is the password,
 * and it is NOT uppercased -- John's rvary has no toupper, and its two vectors
 * both use uppercase passwords so they cannot show the difference. */
static int verify_rvary(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *expected = (unsigned char *)WS->ctx1;
    unsigned char *rv_pt    = (unsigned char *)WS->ctx2;
    unsigned char *ct       = (unsigned char *)WS->ctx3;
    unsigned char *deskey   = (unsigned char *)WS->ctx4;
    DES_key_schedule *ks    = (DES_key_schedule *)WS->ctx5;
    int x, plen;

    if (hashlen != 16) return 0;
    if (hex2bin(hashstr, 16, expected) != 8) return 0;

    plen = passlen > 8 ? 8 : passlen;
    for (x = 0; x < 8; x++) {
        unsigned char ebcdic = (x < plen) ? a2e[pass[x]] : 0x40;
        /* Use the table, not an inline XOR-shift-parity derivation: the
         * two disagree for seven of the 256 byte values, 0x00 among
         * them, so a candidate containing one produced a different key. */
        unsigned char val = (x < plen) ? a2e_pc[pass[x]] : 0x2a;
        deskey[x] = val;              /* == a2e_pc[], derived inline: that
                                       * table is defined later in the file */
        rv_pt[x]  = ebcdic;           /* EBCDIC password, space-padded, NOT
                                       * uppercased -- this is what separates
                                       * RVARY from RACF */
    }
    DES_set_key_unchecked((DES_cblock *)deskey, ks);
    DES_ecb_encrypt((DES_cblock *)rv_pt, (DES_cblock *)ct, ks, DES_ENCRYPT);
    WS->verify_iter = 1;
    return memcmp(ct, expected, 8) == 0;
}

static int verify_racf(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *expected = (unsigned char *)WS->ctx1;
    unsigned char *euser = (unsigned char *)WS->ctx2;
    unsigned char *ciphertext = (unsigned char *)WS->ctx3;
    unsigned char *deskey = (unsigned char *)WS->ctx4;
    DES_key_schedule *ks = (DES_key_schedule *)WS->ctx5;
    const char *colon, *username;
    int hpart, ulen, x;

    /* Handle $racf$*USER*HASH format */
    if (hashlen > 8 && memcmp(hashstr, "$racf$*", 7) == 0) {
        const char *u = hashstr + 7;
        const char *star = memchr(u, '*', hashlen - 7);
        if (!star || (hashlen - (star + 1 - hashstr)) != 16) return 0;
        username = u;
        ulen = star - u;
        if (hex2bin(star + 1, 16, expected) != 8) return 0;
    } else {
        colon = memchr(hashstr, ':', hashlen);
        if (!colon) return 0;
        hpart = colon - hashstr;
        if (hpart != 16) return 0;
        if (hex2bin(hashstr, 16, expected) != 8) return 0;
        username = colon + 1;
        ulen = hashlen - hpart - 1;
    }

    /* Password to DES key: EBCDIC, XOR 0x55, shift left 1, odd parity */
    { int plen = passlen > 8 ? 8 : passlen;
      for (x = 0; x < 8; x++) {
          unsigned char ebcdic = (x < plen) ? a2e[pass[x]] : 0x40;
          /* RACF derives the key inline in mdxfind -- a2e, XOR 0x55, shift left
           * one, odd parity -- and that does NOT agree with the a2e_pc table for
           * seven byte values.  RVARY beside it uses the table.  The two really
           * do differ, so each must follow its own source. */
          unsigned char val = (ebcdic ^ 0x55);
          val = (val << 1) & 0xfe;
          { int bits = 0; unsigned char t = val;
            while (t) { bits += t & 1; t >>= 1; }
            if ((bits & 1) == 0) val |= 1; }
          deskey[x] = val;
      }
    }
    DES_set_key_unchecked((DES_cblock *)deskey, ks);

    /* Uppercase username, pad to 8 with spaces, convert to EBCDIC */
    for (x = 0; x < 8; x++) {
        char c = (x < ulen) ? username[x] : ' ';
        if (c >= 'a' && c <= 'z') c -= 32;
        euser[x] = a2e[(unsigned char)c];
    }
    DES_ecb_encrypt((const_DES_cblock *)euser, (DES_cblock *)ciphertext, ks, DES_ENCRYPT);
    return memcmp(ciphertext, expected, 8) == 0;
}

/* JUNIPERSSG (e856): MD5(user + ":Administration Tools:" + pass) → juniper_encode
 * Format: 30-char encoded ":" username */

static int verify_juniperssg(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    char *encoded = (char *)WS->gp1;
    const char *colon, *username;
    int hpart, ulen;

    /*
     * Two input forms for one algorithm, as SHA1SALTPASS accepts both the plain
     * and the Django spelling:
     *   <30-char hash>:<user>   our registered form
     *   <user>$<30-char hash>   John's md5ns
     * Telling them apart by shape is safe HERE, inside the verifier: a wrong
     * reading simply fails to reproduce the digest and the line is not claimed.
     * The same split at PARSE time would not be safe, because it would rewrite
     * lines belonging to other types before any digest was computed.
     */
    colon = memchr(hashstr, ':', hashlen);
    if (colon && (colon - hashstr) == 30) {
        hpart = 30;
        username = colon + 1;
        ulen = hashlen - hpart - 1;
    } else {
        const char *dollar = memchr(hashstr, '$', hashlen);
        if (!dollar) return 0;
        ulen = (int)(dollar - hashstr);
        if (hashlen - ulen - 1 != 30) return 0;
        username = hashstr;
        hashstr  = dollar + 1;
        hpart    = 30;
    }
    if (ulen < 1) return 0;

    { unsigned char *buf = (unsigned char *)WS->gp2;
      int total = ulen + 22 + passlen;
      if (total > WS_GP_SIZE) return 0;
      memcpy(buf, username, ulen);
      memcpy(buf + ulen, ":Administration Tools:", 22);
      memcpy(buf + ulen + 22, pass, passlen);
      rhash_msg(RHASH_MD5, buf, total, md5);
    }
    juniper_encode(md5, encoded);
    return memcmp(encoded, hashstr, 30) == 0;
}

/* CISCOPIX (e861): MD5(pass padded to 16) → cisco_pix_encode — 16-char encoded */
static int verify_ciscopix(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    unsigned char *padded = (unsigned char *)WS->ctx2;
    char *encoded = (char *)WS->gp1;

    if (hashlen != 16) return 0;
    memset(padded, 0, 16);
    memcpy(padded, pass, passlen > 16 ? 16 : passlen);
    rhash_msg(RHASH_MD5, padded, 16, md5);
    cisco_pix_encode(md5, encoded);
    return memcmp(encoded, hashstr, 16) == 0;
}

/* CISCOASA (e862): MD5((pass+salt) padded to 16/32) → cisco_pix_encode
 * Format: 16-char encoded ":" salt */
static int verify_ciscoasa(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    unsigned char *padded = (unsigned char *)WS->ctx2;
    char *encoded = (char *)WS->gp1;
    const char *colon, *salt;
    int hpart, saltlen, asa_plen, padto;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 16) return 0;
    salt = colon + 1;
    saltlen = hashlen - hpart - 1;

    asa_plen = passlen;
    if (asa_plen + saltlen > 32) asa_plen = 32 - saltlen;
    if (asa_plen < 0) asa_plen = 0;
    memset(padded, 0, 32);
    memcpy(padded, pass, asa_plen);
    memcpy(padded + asa_plen, salt, saltlen);
    padto = (asa_plen + saltlen >= 16) ? 32 : 16;
    rhash_msg(RHASH_MD5, padded, padto, md5);
    cisco_pix_encode(md5, encoded);
    return memcmp(encoded, hashstr, 16) == 0;
}

/* CISCO4 (e865): SHA256(pass) → phpitoa64 big-endian encode — 43 chars */
static int verify_cisco4(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha256 = (unsigned char *)WS->ctx1;
    char *encoded = (char *)WS->gp1;

    if (hashlen != 43) return 0;
    SHA256(pass, passlen, sha256);
    /* php64 big-endian encode: groups of 3 bytes, MSB first */
    { int i, ei = 0;
      for (i = 0; i + 2 < 32; i += 3) {
          unsigned int v = ((unsigned int)sha256[i] << 16) |
                           ((unsigned int)sha256[i+1] << 8) | sha256[i+2];
          encoded[ei++] = phpitoa64[(v >> 18) & 0x3f];
          encoded[ei++] = phpitoa64[(v >> 12) & 0x3f];
          encoded[ei++] = phpitoa64[(v >>  6) & 0x3f];
          encoded[ei++] = phpitoa64[v & 0x3f];
      }
      /* last 2 bytes (32 = 10*3 + 2) */
      { unsigned int v = ((unsigned int)sha256[30] << 16) | ((unsigned int)sha256[31] << 8);
        encoded[ei++] = phpitoa64[(v >> 18) & 0x3f];
        encoded[ei++] = phpitoa64[(v >> 12) & 0x3f];
        encoded[ei++] = phpitoa64[(v >>  6) & 0x3f];
      }
      encoded[ei] = 0;
    }
    return memcmp(encoded, hashstr, 43) == 0;
}

/* CISCOISE (e866): 128x SHA256(salt_bin + pass) — 64hex_hash ":" 64hex_salt */
static int verify_ciscoise(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha256 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    char *computed = (char *)WS->gp1;
    int x;

    /* Format: 64hex_hash + 64hex_salt (128 chars concatenated, no colon) */
    if (hashlen != 128) return 0;
    if (hex2bin(hashstr + 64, 64, salt_bin) != 32) return 0;

    { unsigned char *buf = (unsigned char *)WS->gp2;
      if (32 + passlen > WS_GP_SIZE) return 0;
      memcpy(buf, salt_bin, 32);
      memcpy(buf + 32, pass, passlen);
      SHA256(buf, 32 + passlen, sha256);
    }
    /* 128 more iterations */
    for (x = 0; x < 128; x++)
        SHA256(sha256, 32, sha256);

    prmd5(sha256, computed, 64);
    return strncasecmp(computed, hashstr, 64) == 0;
}

/* SAMSUNGSHA1 (e867): 1024x SHA1(digest + str(i) + pass + salt) — 40hex ":" salt */
static int verify_samsungsha1(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha1 = (unsigned char *)WS->ctx1;
    unsigned char *expected = (unsigned char *)WS->ctx2;
    const char *colon, *salt;
    int hpart, saltlen, siter;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 40) return 0;
    if (hex2bin(hashstr, 40, expected) != 20) return 0;
    salt = colon + 1;
    saltlen = hashlen - hpart - 1;

    /* Every message built below is 1 or 20 bytes of prefix, at most 4 digits
     * of counter, then pass and salt. Bound it once against the workspace
     * buffer: a salt that cannot fit was never a SAMSUNGSHA1 salt, and the
     * alternative is a buffer overrun. */
    if (24 + passlen + saltlen > WS_GP_SIZE) return 0;

    /* iter 0: SHA1("0" + pass + salt) */
    { unsigned char *buf = (unsigned char *)WS->gp1;
      int pos = 0;
      buf[pos++] = '0';
      memcpy(buf + pos, pass, passlen); pos += passlen;
      memcpy(buf + pos, salt, saltlen); pos += saltlen;
      SHA1(buf, pos, sha1);
    }
    /* iter 1-1023: SHA1(prev_digest + str(i) + pass + salt) */
    for (siter = 1; siter < 1024; siter++) {
        unsigned char *buf = (unsigned char *)WS->gp1;
        int pos = 0;
        memcpy(buf, sha1, 20); pos = 20;
        pos += sprintf((char *)buf + pos, "%d", siter);
        memcpy(buf + pos, pass, passlen); pos += passlen;
        memcpy(buf + pos, salt, saltlen); pos += saltlen;
        SHA1(buf, pos, sha1);
    }
    return memcmp(sha1, expected, 20) == 0;
}

/* EPISERVER (e859): SHA1 or SHA256(salt_bin + UTF16LE(pass))
 * Format: $episerver$*V*b64salt*b64hash (V=0 SHA1, V=1 SHA256) */
static int verify_episerver(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *utf16 = (unsigned char *)WS->u16a;
    unsigned char *hash_out = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    unsigned char *expected = (unsigned char *)WS->ctx3;
    int u16len, epiver, hashbytes;
    const char *p, *salt_b64, *hash_b64;
    int salt_b64_len, hash_b64_len, salt_len, exp_len;

    if (hashlen < 20 || memcmp(hashstr, "$episerver$*", 12) != 0) return 0;
    epiver = hashstr[12] - '0';
    if (epiver != 0 && epiver != 1) return 0;
    if (hashstr[13] != '*') return 0;

    salt_b64 = hashstr + 14;
    p = memchr(salt_b64, '*', hashlen - 14);
    if (!p) return 0;
    salt_b64_len = p - salt_b64;
    hash_b64 = p + 1;
    hash_b64_len = hashlen - (hash_b64 - hashstr);

    salt_len = base64_decode(salt_b64, salt_b64_len, salt_bin, WS_CTX_SIZE);
    if (salt_len <= 0) return 0;
    hashbytes = (epiver == 1) ? 32 : 20;
    exp_len = base64_decode(hash_b64, hash_b64_len, expected, WS_CTX_SIZE);
    if (exp_len < hashbytes) return 0;

    u16len = utf8_to_utf16le(pass, passlen, utf16, WS_U16_SIZE);
    if (u16len <= 0) return 0;

    { unsigned char *buf = (unsigned char *)WS->gp1;
      if (salt_len + u16len > WS_GP_SIZE) return 0;
      memcpy(buf, salt_bin, salt_len);
      memcpy(buf + salt_len, utf16, u16len);
      if (epiver == 1)
          SHA256(buf, salt_len + u16len, hash_out);
      else
          SHA1(buf, salt_len + u16len, hash_out);
    }
    return memcmp(hash_out, expected, hashbytes) == 0;
}

/* SYBASE-ASE (e877): SHA256(UTF16BE(pass, 510 bytes) + salt_bin) — 0xc007 + 16hex_salt + 64hex */
static int verify_sybase(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha256 = (unsigned char *)WS->ctx1;
    unsigned char *salt_bin = (unsigned char *)WS->ctx2;
    unsigned char *expected = (unsigned char *)WS->ctx3;
    unsigned char *wbuf = (unsigned char *)WS->gp1;
    int x;

    if (hashlen != 86) return 0;
    if (strncasecmp(hashstr, "0xc007", 6) != 0) return 0;
    if (hex2bin(hashstr + 6, 16, salt_bin) != 8) return 0;
    if (hex2bin(hashstr + 22, 64, expected) != 32) return 0;

    /* UTF-16BE password padded to 510 bytes */
    memset(wbuf, 0, 518);
    for (x = 0; x < passlen && x < 255; x++) {
        wbuf[x * 2] = 0;
        wbuf[x * 2 + 1] = pass[x];
    }
    memcpy(wbuf + 510, salt_bin, 8);
    SHA256(wbuf, 518, sha256);
    return memcmp(sha256, expected, 32) == 0;
}

/* IPMI2-SHA1 (e872): HMAC-SHA1(pass, hex_decoded_salt) — 40hex ":" salt_hex */
static int verify_ipmi2sha1(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *hmac_out = (unsigned char *)WS->ctx1;
    unsigned char *expected = (unsigned char *)WS->ctx2;
    unsigned char *salt_bin = (unsigned char *)WS->gp1;
    unsigned int hmac_len = 20;
    const char *colon, *hash_part, *salt_part;
    int hpart, salt_hex_len, salt_len;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;

    /* Try hash:salt (40hex hash first) or salt:hash (salt first) */
    if (hpart == 40) {
        hash_part = hashstr;
        salt_part = colon + 1;
        salt_hex_len = hashlen - hpart - 1;
    } else {
        salt_part = hashstr;
        salt_hex_len = hpart;
        hash_part = colon + 1;
        if (hashlen - hpart - 1 != 40) return 0;
    }
    if (hex2bin(hash_part, 40, expected) != 20) return 0;
    salt_len = hex2bin(salt_part, salt_hex_len, salt_bin);
    if (salt_len <= 0) return 0;

    HMAC(EVP_sha1(), pass, passlen, salt_bin, salt_len, hmac_out, &hmac_len);
    return memcmp(hmac_out, expected, 20) == 0;
}

/* IPMI2-MD5 (e873): HMAC-MD5(pass, hex_decoded_salt) — 32hex ":" salt_hex */
static int verify_ipmi2md5(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *hmac_out = (unsigned char *)WS->ctx1;
    unsigned char *expected = (unsigned char *)WS->ctx2;
    unsigned char *salt_bin = (unsigned char *)WS->gp1;
    unsigned int hmac_len = 16;
    const char *colon;
    int hpart, salt_hex_len, salt_len;

    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    hpart = colon - hashstr;
    if (hpart != 32) return 0;
    if (hex2bin(hashstr, 32, expected) != 16) return 0;

    salt_hex_len = hashlen - hpart - 1;
    salt_len = hex2bin(colon + 1, salt_hex_len, salt_bin);
    if (salt_len <= 0) return 0;

    HMAC(EVP_md5(), pass, passlen, salt_bin, salt_len, hmac_out, &hmac_len);
    return memcmp(hmac_out, expected, 16) == 0;
}

/* SHA1SALTCX verify: handles iteration internally.
 * Format: hash(40hex):salt
 * Round 1: SHA1("--" + salt + "----" + pass + "----")
 * Round 2+: SHA1("--" + salt + hex(prev,40) + "--" + pass + "----")
 * Tries up to Maxiter rounds, matches any. */
static int verify_sha1saltcx(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *expected = (unsigned char *)WS->ctx1;
    unsigned char *digest = (unsigned char *)WS->ctx2;
    char *hexbuf = (char *)WS->gp1;      /* hex of previous digest */
    const char *colon;
    const char *salt;
    int saltlen;
    int iter;
    rhash ctx;

    /* Parse hash:salt */
    colon = memchr(hashstr, ':', hashlen);
    if (!colon) return 0;
    if (colon - hashstr != 40) return 0;
    if (hex2bin(hashstr, 40, expected) != 20) return 0;
    salt = colon + 1;
    saltlen = hashlen - 41;
    if (saltlen <= 0) return 0;

    /* Round 1: SHA1("--" + salt + "----" + pass + "----") */
    ctx = rhash_init(RHASH_SHA1);
    rhash_update(ctx, "--", 2);
    rhash_update(ctx, salt, saltlen);
    rhash_update(ctx, "----", 4);
    rhash_update(ctx, pass, passlen);
    rhash_update(ctx, "----", 4);
    rhash_final(ctx, digest); rhash_free(ctx);

    if (memcmp(digest, expected, 20) == 0) { WS->verify_iter = 1; return 1; }

    /* Rounds 2+: SHA1("--" + salt + "--" + hex(prev,40) + "--" + pass + "----") */
    for (iter = 2; iter <= Maxiter; iter++) {
        prmd5(digest, hexbuf, 40);
        ctx = rhash_init(RHASH_SHA1);
        rhash_update(ctx, "--", 2);
        rhash_update(ctx, salt, saltlen);
        rhash_update(ctx, "--", 2);
        rhash_update(ctx, hexbuf, 40);
        rhash_update(ctx, "--", 2);
        rhash_update(ctx, pass, passlen);
        rhash_update(ctx, "----", 4);
        rhash_final(ctx, digest); rhash_free(ctx);
        if (memcmp(digest, expected, 20) == 0) { WS->verify_iter = iter; return 1; }
    }
    return 0;
}

/* ISCSI-CHAP (e888): MD5(id_byte || password || challenge_bytes)
 * Format: hash(32hex):challenge(hex):id(2hex) */
static int verify_iscsi_chap(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *md5out = (unsigned char *)WS->ctx1;
    unsigned char *expected = (unsigned char *)WS->ctx2;
    unsigned char *chall_bin = (unsigned char *)WS->gp1;
    unsigned char *input = (unsigned char *)WS->gp2;
    const char *colon1, *colon2;
    int chall_hexlen, chall_binlen;
    unsigned char id_byte;

    /* parse hash:challenge:id */
    colon1 = memchr(hashstr, ':', hashlen);
    if (!colon1) return 0;
    int hpart = colon1 - hashstr;
    if (hpart != 32) return 0;
    if (hex2bin(hashstr, 32, expected) != 16) return 0;

    colon2 = memchr(colon1 + 1, ':', hashstr + hashlen - colon1 - 1);
    if (!colon2) return 0;
    int idlen = hashstr + hashlen - colon2 - 1;
    if (idlen != 2) return 0;

    /* decode id byte */
    if (hex2bin(colon2 + 1, 2, &id_byte) != 1) return 0;

    /* decode challenge */
    chall_hexlen = colon2 - colon1 - 1;
    if (chall_hexlen < 2 || chall_hexlen > (int)WS_GP_SIZE * 2) return 0;
    chall_binlen = hex2bin(colon1 + 1, chall_hexlen, chall_bin);
    if (chall_binlen <= 0) return 0;

    /* MD5(id_byte || password || challenge_bytes) */
    if (1 + passlen + chall_binlen > (int)WS_GP_SIZE) return 0;
    input[0] = id_byte;
    memcpy(input + 1, pass, passlen);
    memcpy(input + 1 + passlen, chall_bin, chall_binlen);
    rhash_msg(RHASH_MD5, input, 1 + passlen + chall_binlen, md5out);
    return memcmp(md5out, expected, 16) == 0;
}

/* Werkzeug MD5: md5$salt$hexhash — HMAC-MD5(key=salt, msg=pass) */
static int verify_werkzeug_md5(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *hmac_out = (unsigned char *)WS->ctx1;
    char *computed = (char *)WS->gp1;
    const char *salt_start, *hash_start;
    int saltlen;
    unsigned int outlen = 16;

    if (hashlen < 8 || memcmp(hashstr, "md5$", 4) != 0) return 0;
    salt_start = hashstr + 4;
    hash_start = memchr(salt_start, '$', hashlen - 4);
    if (!hash_start) return 0;
    saltlen = hash_start - salt_start;
    if (saltlen < 1 || saltlen > 256) return 0;
    hash_start++;
    if (hashlen - (int)(hash_start - hashstr) < 32) return 0;

    HMAC(EVP_md5(), salt_start, saltlen, pass, passlen, hmac_out, &outlen);
    prmd5(hmac_out, computed, 32);
    return strncasecmp(computed, hash_start, 32) == 0;
}

/* Werkzeug SHA256: sha256$salt$hexhash — HMAC-SHA256(key=salt, msg=pass) */
static int verify_werkzeug_sha256(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *hmac_out = (unsigned char *)WS->ctx1;
    char *computed = (char *)WS->gp1;
    const char *salt_start, *hash_start;
    int saltlen;
    unsigned int outlen = 32;

    if (hashlen < 11 || memcmp(hashstr, "sha256$", 7) != 0) return 0;
    salt_start = hashstr + 7;
    hash_start = memchr(salt_start, '$', hashlen - 7);
    if (!hash_start) return 0;
    saltlen = hash_start - salt_start;
    if (saltlen < 1 || saltlen > 256) return 0;
    hash_start++;
    if (hashlen - (int)(hash_start - hashstr) < 64) return 0;

    HMAC(EVP_sha256(), salt_start, saltlen, pass, passlen, hmac_out, &outlen);
    prmd5(hmac_out, computed, 64);
    return strncasecmp(computed, hash_start, 64) == 0;
}

/* AuthMe (e891): $SHA$salt$sha256hex — sha256(sha256hex(pass).salt) */
static int verify_authme(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha_out = (unsigned char *)WS->ctx1;
    char *hexbuf = (char *)WS->gp1;
    char *computed = (char *)WS->gp2;
    const char *salt_start, *hash_start;
    int saltlen;

    if (hashlen < 10 || memcmp(hashstr, "$SHA$", 5) != 0) return 0;
    salt_start = hashstr + 5;
    hash_start = memchr(salt_start, '$', hashlen - 5);
    if (!hash_start) return 0;
    saltlen = hash_start - salt_start;
    if (saltlen < 1 || saltlen > 256) return 0;
    hash_start++;
    if (hashlen - (int)(hash_start - hashstr) < 64) return 0;

    /* sha256(pass) → hex */
    rhash_msg(RHASH_SHA256, pass, passlen, sha_out);
    prmd5(sha_out, hexbuf, 64);
    /* sha256(hex . salt) */
    memcpy(hexbuf + 64, salt_start, saltlen);
    rhash_msg(RHASH_SHA256, (unsigned char *)hexbuf, 64 + saltlen, sha_out);
    prmd5(sha_out, computed, 64);
    return strncasecmp(computed, hash_start, 64) == 0;
}

/* NETWITNESS (e892): sha256(SHA256_HEX_UPPER(pass) . base64_decode(salt))
 * Format: UCHEXHASH:BASE64SALT (64 uppercase hex : base64-encoded salt) */
static int verify_netwitness(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *sha_out = (unsigned char *)WS->ctx1;
    char *hexbuf = (char *)WS->gp1;
    char *computed = (char *)WS->gp2;
    unsigned char *decoded_salt = (unsigned char *)WS->gp3;
    const char *b64salt;
    int saltlen, dlen;

    if (hashlen < 66) return 0;
    if (hashstr[64] != ':') return 0;
    b64salt = hashstr + 65;
    saltlen = hashlen - 65;
    if (saltlen < 1 || saltlen > 256) return 0;

    /* Decode base64 salt */
    dlen = base64_decode(b64salt, saltlen, decoded_salt, WS_GP_SIZE);
    if (dlen < 1) return 0;

    /* sha256(pass) → uppercase hex */
    rhash_msg(RHASH_SHA256, pass, passlen, sha_out);
    prmd5UC(sha_out, hexbuf, 64);
    /* sha256(uppercase_hex . decoded_salt) */
    memcpy(hexbuf + 64, decoded_salt, dlen);
    rhash_msg(RHASH_SHA256, (unsigned char *)hexbuf, 64 + dlen, sha_out);
    prmd5UC(sha_out, computed, 64);
    return strncasecmp(computed, hashstr, 64) == 0;
}

/* KRB5PA23 (e874): NTLM → HMAC-MD5(usage=1) → RC4 decrypt → verify timestamp
 * Format: $krb5pa$23$user$realm$data$enc_timestamp_hex+checksum_hex */
static int verify_krb5pa23(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *ntlm = (unsigned char *)WS->ctx1;
    unsigned char *k1 = (unsigned char *)WS->ctx2;
    unsigned char *k3 = (unsigned char *)WS->ctx3;
    unsigned char *enc_bin = (unsigned char *)WS->gp1;
    unsigned char *decrypted = (unsigned char *)WS->gp2;
    unsigned int hmac_len;
    const char *p;
    int dc, enc_hex_len, enc_len, data_len;

    if (hashlen < 30 || memcmp(hashstr, "$krb5pa$23$", 11) != 0) return 0;

    /* Skip past user$realm$data$ to get enc_hex */
    p = hashstr + 11;
    dc = 0;
    while (*p && dc < 3 && (p - hashstr) < hashlen) { if (*p == '$') dc++; p++; }
    if (dc != 3) return 0;

    enc_hex_len = hashlen - (p - hashstr);
    enc_len = enc_hex_len / 2;
    if (enc_len < 36 || enc_len > (int)WS_GP_SIZE) return 0;
    if (hex2bin(p, enc_hex_len, enc_bin) != enc_len) return 0;

    /* Compute NTLM hash: MD4(UTF16LE(pass)) */
    { unsigned char utf16[1024];
      int u16len = latin1_to_utf16le(pass, passlen, utf16, sizeof(utf16));
      if (u16len <= 0) return 0;
      rhash_msg(RHASH_MD4, utf16, u16len, ntlm);
    }

    /* K1 = HMAC-MD5(ntlm, usage_type=1) */
    { unsigned char usage[4] = {1, 0, 0, 0};
      hmac_len = 16;
      HMAC(EVP_md5(), ntlm, 16, usage, 4, k1, &hmac_len);
    }

    /* checksum = last 16 bytes, encrypted data = first enc_len-16 bytes */
    data_len = enc_len - 16;

    /* K3 = HMAC-MD5(K1, checksum) */
    hmac_len = 16;
    HMAC(EVP_md5(), k1, 16, enc_bin + data_len, 16, k3, &hmac_len);

    /* RC4 decrypt */
    { hp_rc4_key rc4key;
      hp_rc4_set_key(&rc4key, 16, k3);
      hp_rc4(&rc4key, data_len, enc_bin, decrypted);
    }

    /* Definitive verification: recompute the RC4-HMAC checksum over the full
     * decrypted data and require all 16 bytes to match the stored checksum
     * (the PA-ENC-TS timestamp heuristic is not cryptographic). k3 is reused as
     * the 16-byte scratch -- no longer needed after the RC4 decrypt. */
    if (data_len < 16) return 0;
    hmac_len = 16;
    HMAC(EVP_md5(), k1, 16, decrypted, data_len, k3, &hmac_len);
    return memcmp(k3, enc_bin + data_len, 16) == 0;
}

/* AIX-MD5 (e868): md5crypt with empty magic — {smd5}salt$encoded */
static int verify_aixmd5(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    /* Reuse APR1/md5crypt logic but with empty magic "" */
    unsigned char *md5 = (unsigned char *)WS->ctx1;
    unsigned char *alt = (unsigned char *)WS->ctx2;
    const char *salt;
    int saltlen, i, plen;
    static const char itoa64[] =
        "./0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    if (hashlen < 10 || memcmp(hashstr, "{smd5}", 6) != 0) return 0;
    salt = hashstr + 6;
    for (saltlen = 0; saltlen < 8 && salt[saltlen] && salt[saltlen] != '$'; saltlen++)
        ;
    if (salt[saltlen] != '$') return 0;

    plen = passlen;

    /* Step 1: alt = MD5(pass + salt + pass) — compute first to avoid
     * aliasing with ctx (ws_rhash_init reuses single MD5 context) */
    { rhash ctx;
      ctx = rhash_init(RHASH_MD5);
      rhash_update(ctx, pass, plen);
      rhash_update(ctx, salt, saltlen);
      rhash_update(ctx, pass, plen);
      rhash_final(ctx, alt); rhash_free(ctx);

      /* Step 2: MD5(pass + salt + alt_bytes...) — no magic for AIX */
      ctx = rhash_init(RHASH_MD5);
      rhash_update(ctx, pass, plen);
      rhash_update(ctx, salt, saltlen);

      for (i = plen; i > 0; i -= 16)
          rhash_update(ctx, alt, (i > 16) ? 16 : i);
      for (i = plen; i > 0; i >>= 1) {
          if (i & 1) rhash_update(ctx, "", 1);
          else rhash_update(ctx, pass, 1);
      }
      rhash_final(ctx, md5); rhash_free(ctx);
    }

    /* 1000 iterations */
    for (i = 0; i < 1000; i++) {
        rhash ctx = rhash_init(RHASH_MD5);
        if (i & 1) rhash_update(ctx, pass, plen);
        else rhash_update(ctx, md5, 16);
        if (i % 3) rhash_update(ctx, salt, saltlen);
        if (i % 7) rhash_update(ctx, pass, plen);
        if (i & 1) rhash_update(ctx, md5, 16);
        else rhash_update(ctx, pass, plen);
        rhash_final(ctx, md5); rhash_free(ctx);
    }

    /* md5crypt encoding */
    { static const unsigned char grp[][3] = {
          {0,6,12}, {1,7,13}, {2,8,14}, {3,9,15}, {4,10,5}
      };
      char *enc = (char *)WS->gp1;
      int eidx = 0, g;
      unsigned int v;
      for (g = 0; g < 5; g++) {
          v = ((unsigned int)md5[grp[g][0]] << 16)
            | ((unsigned int)md5[grp[g][1]] << 8)
            | md5[grp[g][2]];
          enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
          enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
          enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
          enc[eidx++] = itoa64[v & 0x3f];
      }
      v = md5[11];
      enc[eidx++] = itoa64[v & 0x3f]; v >>= 6;
      enc[eidx++] = itoa64[v & 0x3f];
      enc[eidx] = 0;

      { char expected[128];
        snprintf(expected, sizeof(expected), "{smd5}%.*s$%s", saltlen, salt, enc);
        return strncmp(expected, hashstr, hashlen) == 0;
      }
    }
}

/* AIX-SHA1 (e869): PBKDF2-HMAC-SHA1 — {ssha1}NN$salt$encoded */
static int verify_aixsha1(const char *hashstr, int hashlen,
    const unsigned char *pass, int passlen)
{
    unsigned char *derived = (unsigned char *)WS->ctx1;
    char *encoded = (char *)WS->gp1;
    const char *p;
    int nn, saltlen;
    unsigned long rounds;

    if (hashlen < 15 || memcmp(hashstr, "{ssha1}", 7) != 0) return 0;
    p = hashstr + 7;
    nn = (p[0] - '0') * 10 + (p[1] - '0');
    if (p[2] != '$') return 0;
    rounds = 1UL << nn;

    { const char *salt_start = p + 3;
      const char *dollar = memchr(salt_start, '$', hashlen - (salt_start - hashstr));
      if (!dollar) return 0;
      saltlen = dollar - salt_start;

      PKCS5_PBKDF2_HMAC((const char *)pass, passlen,
          (const unsigned char *)salt_start, saltlen, rounds,
          EVP_sha1(), 20, derived);
      aix_encode(derived, 20, encoded);

      { char expected[256];
        snprintf(expected, sizeof(expected), "{ssha1}%02d$%.*s$%s", nn, saltlen, salt_start, encoded);
        return strncmp(expected, hashstr, hashlen) == 0;
      }
    }
}

